import React, { useEffect, useState } from 'react';
import { mangaApi } from '@/services/manga-api';
import { ChapterResponse, SeriesResponse } from '@/types/manga';
import {
  CreatePublicationScheduleRequest,
  IssueResponse,
  PublicationScheduleResponse,
  PublicationType,
} from '@/types/editorial';

interface Props {
  schedules: PublicationScheduleResponse[];
  issues: IssueResponse[];
  onCreate: (data: CreatePublicationScheduleRequest) => Promise<boolean>;
  onPublish: (scheduleId: string) => Promise<boolean>;
  publishingScheduleId: string | null;
  isSubmitting: boolean;
}

const typeLabel: Record<PublicationType, string> = {
  [PublicationType.Weekly]: 'Weekly',
  [PublicationType.Monthly]: 'Monthly',
  [PublicationType.OneShot]: 'One-shot',
  [PublicationType.SpecialIssue]: 'Special issue',
};

const statusLabel = {
  1: 'Scheduled',
  2: 'Published',
  3: 'Hiatus',
  4: 'Cancelled',
} as const;

export default function BoardBottomRow({
  schedules,
  issues,
  onCreate,
  onPublish,
  publishingScheduleId,
  isSubmitting,
}: Props) {
  const [series, setSeries] = useState<SeriesResponse[]>([]);
  const [seriesId, setSeriesId] = useState('');
  const [chapters, setChapters] = useState<ChapterResponse[]>([]);
  const [chapterId, setChapterId] = useState('');
  const [issueId, setIssueId] = useState('');
  const [publicationType, setPublicationType] = useState(PublicationType.Weekly);
  const [scheduledDate, setScheduledDate] = useState('');
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    void mangaApi
      .getSeries()
      .then((r) =>
        setSeries(r.data.success ? r.data.data : [])
      )
      .catch(() => setLoadError('Không thể tải Series.'));
  }, []);

  useEffect(() => {
    if (!seriesId) return;
    void mangaApi
      .getChapters(seriesId)
      .then((r) =>
        setChapters(r.data.success ? r.data.data : [])
      )
      .catch(() => setLoadError('Không thể tải Chapter.'));
  }, [seriesId]);

  useEffect(() => {
    if (!seriesId) {
      setChapterId('');
      setChapters([]);
    }
  }, [seriesId]);

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!seriesId || !chapterId || !scheduledDate) return;

    const saved = await onCreate({
      seriesId,
      chapterId,
      ...(issueId ? { issueId } : {}),
      publicationType,
      scheduledDate: new Date(scheduledDate).toISOString(),
    });

    if (saved) {
      setChapterId('');
      setIssueId('');
      setScheduledDate('');
    }
  };

  const handlePublish = async (scheduleId: string) => {
    if (window.confirm("Are you sure you want to publish this schedule? This action will make it live immediately.")) {
      await onPublish(scheduleId);
    }
  };

  const getSeriesTitle = (id: string) => series.find((s) => s.id === id)?.title || id;
  const approvedSeries = series.filter((s) => s.status === 3 || (s.status as string | number) === 'Approved');

  return (
    <div className="grid lg:grid-cols-2 gap-6">
      {/* Create Publication Schedule Form */}
      <form
        onSubmit={submit}
        className="bg-white rounded-2xl border p-5 space-y-3"
      >
        <h3 className="font-bold">Tạo lịch xuất bản</h3>

        {loadError && <p className="text-sm text-rose-600">{loadError}</p>}

        <select
          aria-label="Series"
          required
          value={seriesId}
          onChange={(e) => setSeriesId(e.target.value)}
          className="w-full border p-2 rounded"
        >
          <option value="">Chọn Series</option>
          {approvedSeries.map((item) => (
            <option key={item.id} value={item.id}>
              {item.title}
            </option>
          ))}
        </select>

        <select
          aria-label="Chapter"
          required
          disabled={!seriesId}
          value={chapterId}
          onChange={(e) => setChapterId(e.target.value)}
          className="w-full border p-2 rounded"
        >
          <option value="">Chọn Chapter</option>
          {chapters.map((item) => (
            <option key={item.id} value={item.id}>
              Chapter {item.chapterNumber}
              {item.title ? ` — ${item.title}` : ''}
            </option>
          ))}
        </select>

        <select
          aria-label="Issue optional"
          value={issueId}
          onChange={(e) => setIssueId(e.target.value)}
          className="w-full border p-2 rounded"
        >
          <option value="">Không gắn Issue</option>
          {issues.map((item) => (
            <option key={item.id} value={item.id}>
              {item.issueNumber} — {item.title}
            </option>
          ))}
        </select>

        <select
          aria-label="Publication type"
          value={publicationType}
          onChange={(e) =>
            setPublicationType(Number(e.target.value) as PublicationType)
          }
          className="w-full border p-2 rounded"
        >
          {Object.values(PublicationType)
            .filter((value) => typeof value === 'number')
            .map((value) => (
              <option key={value} value={value}>
                {typeLabel[value as PublicationType]}
              </option>
            ))}
        </select>

        <input
          aria-label="Scheduled date"
          required
          type="datetime-local"
          value={scheduledDate}
          onChange={(e) => setScheduledDate(e.target.value)}
          className="w-full border p-2 rounded"
        />

        <button
          disabled={isSubmitting || !chapterId}
          className="px-4 py-2 bg-slate-800 text-white rounded disabled:opacity-50"
        >
          {isSubmitting ? 'Đang tạo…' : 'Tạo lịch'}
        </button>
      </form>

      {/* Publication Schedule List */}
      <section className="bg-white rounded-2xl border p-5">
        <h3 className="font-bold mb-3">Lịch xuất bản</h3>

        {schedules.length === 0 ? (
          <p className="text-sm text-slate-500">Chưa có lịch xuất bản.</p>
        ) : (
          <ul className="space-y-3">
            {schedules.map((item) => (
              <li key={item.id} className="border-b pb-2 text-sm">
                <p>Series: {getSeriesTitle(item.seriesId)}</p>
                <p>
                  Chapter: {item.chapterId} · {typeLabel[item.publicationType]}
                </p>
                <p>Status: {statusLabel[item.status]}</p>
                <p>{new Date(item.scheduledDate).toLocaleString()}</p>
                {item.publishedAt && (
                  <p>
                    Published:{' '}
                    {new Date(item.publishedAt).toLocaleString()}
                  </p>
                )}
                {item.status === 1 && (
                  <button
                    type="button"
                    disabled={publishingScheduleId === item.id}
                    onClick={() => void handlePublish(item.id)}
                    className="mt-2 px-3 py-1 bg-emerald-700 text-white rounded disabled:opacity-50"
                  >
                    {publishingScheduleId === item.id
                      ? 'Đang xuất bản…'
                      : 'Publish'}
                  </button>
                )}
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

'use client';
import React, { useEffect, useState } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import { AlertCircle, CheckCircle2, X } from 'lucide-react';
import BoardSidebar from './BoardSidebar';
import BoardHeader from './BoardHeader';
import BoardVotingPanel from './BoardVotingPanel';
import RankingTable from './RankingTable';
import BoardBottomRow from './BoardBottomRow';
import IssueManagement from './IssueManagement';
import CancellationRiskPanel from './CancellationRiskPanel';
import { ActiveNav } from '@/types/board';
import { useBoardDashboard } from '@/hooks/useBoardDashboard';
import { useAuthStore } from '@/store/auth-store';

const EMPTY_ROLES: string[] = [];

export function BoardDashboard() {
  const board = useBoardDashboard();
  const searchParams = useSearchParams();
  const router = useRouter();

  const querySeriesId = searchParams.get('seriesId') || '';
  const queryTab = (searchParams.get('tab') as ActiveNav) || 'Dashboard';

  const [activeNav, setActiveNav] = useState<ActiveNav>(queryTab);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [selectedSeriesId, setSelectedSeriesId] = useState(querySeriesId);

  const loadSeriesInsights = board.loadSeriesInsights;
  const clearBoardError = board.clearError;
  const boardError = board.error;

  const updateQuery = (seriesId: string, tab: ActiveNav) => {
    const params = new URLSearchParams();
    if (seriesId) params.set('seriesId', seriesId);
    if (tab) params.set('tab', tab);
    router.replace(`/board?${params.toString()}`);
  };

  const handleNavigate = (tab: ActiveNav) => {
    setActiveNav(tab);
    updateQuery(selectedSeriesId, tab);
  };

  useEffect(() => {
    if (selectedSeriesId || !board.series[0]) return;
    const timer = window.setTimeout(() => {
      setSelectedSeriesId(board.series[0].id);
      updateQuery(board.series[0].id, activeNav);
    }, 0);
    return () => window.clearTimeout(timer);
  }, [board.series, selectedSeriesId]);

  const loadVoteSummary = board.loadVoteSummary;

  useEffect(() => {
    if (selectedSeriesId) {
      void loadSeriesInsights(selectedSeriesId);
      void loadVoteSummary(selectedSeriesId);
    }
  }, [loadSeriesInsights, loadVoteSummary, selectedSeriesId]);

  useEffect(() => {
    if (!boardError) return;
    const timer = setTimeout(clearBoardError, 5000);
    return () => clearTimeout(timer);
  }, [boardError, clearBoardError]);

  const isDraft = (status: any) => status === 1 || status === 'Draft';
  const isSubmitted = (status: any) => status === 2 || status === 'Submitted';

  // Proposal queue filtering: Draft must NOT appear in the Board Queue
  const visibleSeries = board.series.filter((item) => !isDraft(item.status));
  const submittedSeries = visibleSeries.filter((item) => isSubmitted(item.status));

  const selected = visibleSeries.find((item) => item.id === selectedSeriesId) || null;
  const storedRoles = useAuthStore((state) => state.user?.roles);
  const roles = storedRoles ?? EMPTY_ROLES;
  const canManageIssues = roles.some((role) =>
    ['editorialboard', 'admin'].includes(role.toLowerCase())
  );

  const voting = (
    <section className="bg-white rounded-2xl border p-5">
      <h2 className="font-bold mb-3">Board voting</h2>
      <select
        aria-label="Series to vote"
        value={selectedSeriesId}
        onChange={(e) => {
          setSelectedSeriesId(e.target.value);
          updateQuery(e.target.value, activeNav);
        }}
        className="border rounded p-2 mb-4 w-full"
      >
        <option value="">Chọn Series</option>
        {submittedSeries.map((item) => (
          <option key={item.id} value={item.id}>
            {item.title}
          </option>
        ))}
      </select>
      <BoardVotingPanel
        proposal={selected}
        summary={selected ? board.voteSummaries[selected.id] || null : null}
        onVote={board.voteProposal}
        onFinalize={board.finalizeProposal}
        isVoting={board.isVoting}
        isFinalizing={board.isFinalizing}
      />
    </section>
  );

  const rankings = (
    <RankingTable
      issues={board.issues}
      series={visibleSeries}
      selectedIssueId={board.selectedIssueId}
      rankings={board.rankings}
      isLoading={board.isRankingLoading}
      onIssueChange={(id) => void board.selectIssue(id)}
      onReaderVote={board.inputReaderVote}
      onRecalculate={board.calculateRanking}
      onRetry={() =>
        board.selectedIssueId ? board.selectIssue(board.selectedIssueId) : Promise.resolve()
      }
    />
  );

  const schedules = (
    <BoardBottomRow
      schedules={board.schedules}
      issues={board.issues}
      onCreate={board.createSchedule}
      onPublish={board.publishSchedule}
      publishingScheduleId={board.publishingScheduleId}
      isSubmitting={board.isScheduling}
    />
  );

  const cancellation = (
    <CancellationRiskPanel
      series={visibleSeries}
      selectedSeriesId={selectedSeriesId}
      warnings={board.cancellationWarnings}
      rankingHistory={board.rankingHistory}
      isLoading={board.isSeriesActionLoading}
      onSeriesChange={(id) => {
        setSelectedSeriesId(id);
        updateQuery(id, activeNav);
      }}
      onStatusChange={(action) => board.setSeriesStatus(selectedSeriesId, action)}
    />
  );

  const content =
    activeNav === 'Issue Management' ? (
      <IssueManagement
        issues={board.issues}
        canManage={canManageIssues}
        onCreate={board.createIssue}
        onStatusChange={(issueId, status) => board.updateIssueStatus(issueId, { status })}
        onRefresh={board.fetchBoardData}
        onRankingCalculated={board.applyCalculatedRanking}
      />
    ) : activeNav === 'Board Voting' ? (
      voting
    ) : activeNav === 'Rankings' ? (
      rankings
    ) : activeNav === 'Cancellation Review' || activeNav === 'Decision History' ? (
      cancellation
    ) : activeNav === 'Publication Schedule' ? (
      schedules
    ) : (
      <div className="space-y-6">
        {voting}
        {rankings}
        {cancellation}
        {schedules}
      </div>
    );

  return (
    <div className="flex h-screen bg-slate-50">
      <BoardSidebar active={activeNav} onNavigate={handleNavigate} open={sidebarOpen} />
      <div className="flex-1 min-w-0 overflow-auto">
        <BoardHeader onToggleSidebar={() => setSidebarOpen((value) => !value)} />
        <div className="p-6 space-y-4">
          {board.error && (
            <div className="p-3 bg-rose-50 text-rose-700 rounded flex justify-between">
              <span>
                <AlertCircle size={14} className="inline mr-2" />
                {board.error}
              </span>
              <button onClick={board.clearError}>
                <X size={14} />
              </button>
            </div>
          )}
          {board.successMessage && (
            <div className="p-3 bg-emerald-50 text-emerald-700 rounded flex justify-between">
              <span>
                <CheckCircle2 size={14} className="inline mr-2" />
                {board.successMessage}
              </span>
              <button onClick={board.clearSuccess}>
                <X size={14} />
              </button>
            </div>
          )}
          {board.isLoading && <p>Đang tải workspace…</p>}
          {content}
        </div>
      </div>
    </div>
  );
}

