'use client';

import { useEffect, useState } from 'react';
import { Layers, Plus, X, AlertCircle, Loader2, MessageSquare, Highlighter, Eye, MousePointerClick } from 'lucide-react';
import { mangaApi } from '@/services/manga-api';
import { fileApi } from '@/services/file-api';
import { PageResponse, AnnotationType, AnnotationResponse } from '@/types/manga';
import { usePageAnnotations } from '@/hooks/usePageAnnotations';

interface MangakaPageEditorTabProps {
  triggerModal: (title: string, content: string) => void;
}

export default function MangakaPageEditorTab({ triggerModal }: MangakaPageEditorTabProps) {
  const [pages, setPages] = useState<PageResponse[]>([]);
  const [chapterId, setChapterId] = useState('');
  const [selectedPageId, setSelectedPageId] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Visual Image URL state
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [imageLoading, setImageLoading] = useState(false);

  // Interactive Drawing states
  const [isDrawing, setIsDrawing] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [currentBox, setCurrentBox] = useState<{ x: number; y: number; width: number; height: number } | null>(null);

  // Annotation form state
  const [showAnnotationForm, setShowAnnotationForm] = useState(false);
  const [annotationType, setAnnotationType] = useState<AnnotationType>('Other');
  const [annotationText, setAnnotationText] = useState('');
  const [annotationSubmitting, setAnnotationSubmitting] = useState(false);

  // Use annotation hook for selected page
  const { annotations, loading: annotationsLoading, createAnnotation, deleteAnnotation } =
    usePageAnnotations(selectedPageId);

  useEffect(() => {
    const storedChapterId = window.localStorage.getItem('manga-current-chapter-id');
    if (storedChapterId) {
      setChapterId(storedChapterId);
      void loadPages(storedChapterId);
    }
  }, []);

  // Fetch page image url when selected page changes
  useEffect(() => {
    setImageUrl(null);
    if (!selectedPageId) return;

    const pageObj = pages.find((p) => p.id === selectedPageId);
    if (pageObj?.fileId) {
      setImageLoading(true);
      fileApi
        .getFileUrl(pageObj.fileId)
        .then((res) => {
          if (res.data?.success && res.data.data?.url) {
            setImageUrl(res.data.data.url);
          }
        })
        .catch((err) => {
          console.error('Failed to load page image URL:', err);
        })
        .finally(() => {
          setImageLoading(false);
        });
    }
  }, [selectedPageId, pages]);

  const loadPages = async (currentChapterId: string) => {
    setLoading(true);
    setError(null);
    try {
      const res = await mangaApi.getPages(currentChapterId);
      if (res.data?.success) {
        setPages(res.data.data || []);
      } else {
        setError(res.data?.message || 'Unable to load pages.');
      }
    } catch (err: unknown) {
      const error = err as { response?: { data?: { message?: string; error?: string } } };
      setError(error.response?.data?.message || error.response?.data?.error || 'Could not reach manga service.');
    } finally {
      setLoading(false);
    }
  };

  const handleCreatePage = async () => {
    if (!chapterId) {
      triggerModal('Select a chapter first', 'Open the Chapters tab and pick a chapter before creating pages.');
      return;
    }

    try {
      const res = await mangaApi.createPage(chapterId, { pageNumber: pages.length + 1 });
      if (res.data?.success) {
        triggerModal('Page Created', 'A new page record was created for the selected chapter.');
        void loadPages(chapterId);
      } else {
        triggerModal('Page Creation Failed', res.data?.message || 'The page could not be created.');
      }
    } catch (err: unknown) {
      const error = err as { response?: { data?: { message?: string } } };
      triggerModal('Page Creation Failed', error.response?.data?.message || 'The page could not be created.');
    }
  };

  // Drawing Canvas coordinates mouse handlers
  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    if (annotationSubmitting || !imageUrl) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    setIsDrawing(true);
    setStartPos({ x, y });
    setCurrentBox({ x, y, width: 0, height: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isDrawing || !currentBox || !imageUrl) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const currentX = ((e.clientX - rect.left) / rect.width) * 100;
    const currentY = ((e.clientY - rect.top) / rect.height) * 100;

    const x = Math.min(startPos.x, currentX);
    const y = Math.min(startPos.y, currentY);
    const width = Math.abs(startPos.x - currentX);
    const height = Math.abs(startPos.y - currentY);

    setCurrentBox({ x, y, width, height });
  };

  const handleMouseUp = () => {
    if (!isDrawing || !imageUrl) return;
    setIsDrawing(false);

    // Only open annotation form if selection box is large enough (avoid random clicks)
    if (currentBox && (currentBox.width > 1.5 || currentBox.height > 1.5)) {
      setShowAnnotationForm(true);
    } else {
      setCurrentBox(null);
    }
  };

  const handleAddAnnotation = async () => {
    if (!selectedPageId || !annotationText.trim()) {
      setError('Please enter annotation text.');
      return;
    }

    setAnnotationSubmitting(true);
    const success = await createAnnotation({
      type: annotationType,
      description: annotationText.trim(),
      notes: `Added via visual page editor`,
      coordinatesJson: currentBox ? JSON.stringify(currentBox) : undefined,
    });

    setAnnotationSubmitting(false);

    if (success) {
      setAnnotationText('');
      setShowAnnotationForm(false);
      setCurrentBox(null);
      triggerModal('Annotation Added', 'Your annotation has been saved with coordinates.');
    } else {
      setError('Failed to create annotation.');
    }
  };

  const handleDeleteAnnotation = async (annotationId: string) => {
    if (!window.confirm('Delete this annotation?')) return;
    const success = await deleteAnnotation(annotationId);
    if (success) {
      triggerModal('Annotation Deleted', 'The annotation has been removed.');
    }
  };

  const getAnnotationTypeColor = (type: AnnotationType) => {
    switch (type) {
      case 'comment':
        return 'bg-blue-50/70 text-blue-700 border-blue-200';
      case 'highlight':
        return 'bg-amber-50/70 text-amber-700 border-amber-200';
      case 'error':
        return 'bg-rose-50/70 text-rose-700 border-rose-200';
      case 'correction':
        return 'bg-purple-50/70 text-purple-700 border-purple-200';
      default:
        return 'bg-slate-50/70 text-slate-700 border-slate-200';
    }
  };

  const getAnnotationBorderColor = (type: AnnotationType) => {
    switch (type) {
      case 'comment':
        return 'border-blue-500 bg-blue-500/10';
      case 'highlight':
        return 'border-amber-500 bg-amber-500/10';
      case 'error':
        return 'border-rose-500 bg-rose-500/10';
      case 'correction':
        return 'border-purple-500 bg-purple-500/10';
      default:
        return 'border-slate-500 bg-slate-500/10';
    }
  };

  const getAnnotationTypeIcon = (type: AnnotationType) => {
    switch (type) {
      case 'comment':
        return <MessageSquare size={14} />;
      case 'highlight':
        return <Highlighter size={14} />;
      case 'error':
        return <AlertCircle size={14} />;
      case 'correction':
        return <Plus size={14} />;
      default:
        return null;
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Visual Page Editor & Annotations</h1>
          <p className="text-xs text-slate-500 font-semibold mt-1">
            Review layout files visually, click and drag to define coordinate boxes, and allocate task requirements.
          </p>
        </div>
        <button
          onClick={handleCreatePage}
          className="inline-flex items-center gap-2 rounded-lg bg-indigo-650 px-3 py-2 text-xs font-bold text-white hover:bg-indigo-750 transition-colors"
        >
          <Plus size={14} />
          Add Page
        </button>
      </div>

      {loading ? (
        <div className="rounded-xl border border-slate-150 bg-white p-8 flex items-center justify-center gap-3 shadow-sm">
          <Loader2 className="animate-spin text-slate-400" size={20} />
          <span className="text-sm text-slate-500">Loading pages…</span>
        </div>
      ) : error && pages.length === 0 ? (
        <div className="rounded-xl border border-rose-200 bg-rose-50/30 p-6">
          <p className="text-sm text-rose-700 font-semibold">{error}</p>
        </div>
      ) : pages.length === 0 ? (
        <div className="bg-white border border-slate-150 rounded-xl p-8 text-center max-w-xl mx-auto shadow-sm">
          <div className="h-16 w-16 bg-indigo-50 border border-indigo-100 text-indigo-700 rounded-full flex items-center justify-center mx-auto mb-4">
            <Layers size={28} />
          </div>
          <h3 className="text-lg font-bold text-slate-800">No pages created yet</h3>
          <p className="text-sm text-slate-500 font-semibold mt-1.5 max-w-md mx-auto">
            Create your first page to start adding annotations and managing your layout.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left panel: Page List */}
          <div className="space-y-4 lg:col-span-1">
            <h3 className="text-[11px] font-bold text-slate-500 uppercase tracking-wider">Page List</h3>
            <div className="grid gap-3 grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 max-h-[500px] overflow-y-auto pr-1">
              {pages.map((page) => (
                <div
                  key={page.id}
                  onClick={() => setSelectedPageId(page.id)}
                  className={`rounded-xl border p-4 cursor-pointer transition-all ${
                    selectedPageId === page.id
                      ? 'border-indigo-500 bg-indigo-50/10 shadow-md ring-1 ring-indigo-500/20'
                      : 'border-slate-200 bg-white hover:border-slate-300'
                  }`}
                >
                  <div className="mb-2.5 flex items-center justify-between">
                    <span className="text-xs font-black text-slate-800">
                      Page {page.pageNumber}
                    </span>
                    <span className="text-[9px] font-bold uppercase tracking-wider text-slate-500 bg-slate-100 px-2 py-0.5 rounded">
                      {page.status}
                    </span>
                  </div>
                  <div className="rounded-lg border border-slate-100 bg-slate-50 p-2.5 text-xs text-slate-650 min-h-16 flex items-center">
                    {page.fileId ? (
                      <div className="space-y-0.5 min-w-0">
                        <p className="text-[10px] font-semibold text-slate-500 uppercase font-mono tracking-wider">File Attached</p>
                        <p className="text-[10px] font-mono break-all text-indigo-600 font-semibold">{page.fileId}</p>
                      </div>
                    ) : (
                      <p className="text-[11px] text-slate-400 font-semibold italic">No canvas file attached yet.</p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Right panel: Active Editor View */}
          <div className="lg:col-span-2 space-y-6">
            {selectedPageId ? (
              <div className="grid grid-cols-1 md:grid-cols-5 gap-6">
                {/* Visual Workspace Canvas (3/5 cols) */}
                <div className="md:col-span-3 space-y-3">
                  <h3 className="text-[11px] font-bold text-slate-500 uppercase tracking-wider">Visual Workspace</h3>

                  {imageLoading ? (
                    <div className="aspect-[3/4] rounded-2xl border border-slate-200 bg-white flex flex-col items-center justify-center gap-3">
                      <Loader2 className="animate-spin text-indigo-500" size={24} />
                      <p className="text-xs text-slate-400 font-semibold">Loading page file...</p>
                    </div>
                  ) : imageUrl ? (
                    <div className="relative group/canvas">
                      {/* Interactive Selection area */}
                      <div
                        onMouseDown={handleMouseDown}
                        onMouseMove={handleMouseMove}
                        onMouseUp={handleMouseUp}
                        className="relative w-full aspect-[3/4] rounded-2xl overflow-hidden border border-slate-200 select-none cursor-crosshair bg-slate-900 shadow-lg"
                      >
                        {/* Page manuscript image */}
                        <img
                          src={imageUrl}
                          alt="Manuscript"
                          className="w-full h-full object-contain pointer-events-none"
                        />

                        {/* Existing saved annotations overlays */}
                        {annotations.map((annot) => {
                          if (!annot.coordinatesJson) return null;
                          try {
                            const box = JSON.parse(annot.coordinatesJson);
                            return (
                              <div
                                key={annot.id}
                                className={`absolute border-2 pointer-events-none rounded transition-all duration-300 ${getAnnotationBorderColor(
                                  (annot.type || 'comment') as AnnotationType
                                )}`}
                                style={{
                                  left: `${box.x}%`,
                                  top: `${box.y}%`,
                                  width: `${box.width}%`,
                                  height: `${box.height}%`,
                                }}
                              >
                                <div className="absolute top-1 left-1 px-1.5 py-0.5 rounded text-[8px] font-bold uppercase tracking-wider bg-slate-950/80 text-white font-mono leading-none border border-white/10 opacity-0 group-hover/canvas:opacity-100 transition-opacity">
                                  {annot.type}
                                </div>
                              </div>
                            );
                          } catch {
                            return null;
                          }
                        })}

                        {/* Active box drawing overlay */}
                        {isDrawing && currentBox && (
                          <div
                            className="absolute border-2 border-dashed border-indigo-400 bg-indigo-500/20 rounded pointer-events-none"
                            style={{
                              left: `${currentBox.x}%`,
                              top: `${currentBox.y}%`,
                              width: `${currentBox.width}%`,
                              height: `${currentBox.height}%`,
                            }}
                          />
                        )}
                      </div>
                      <div className="flex items-center justify-center gap-1.5 text-[10px] text-slate-500 mt-2 font-bold uppercase tracking-wider">
                        <MousePointerClick size={12} className="text-indigo-500" />
                        <span>Click and drag on the image above to define an annotation box</span>
                      </div>
                    </div>
                  ) : (
                    <div className="aspect-[3/4] rounded-2xl border-2 border-dashed border-slate-250 bg-slate-50/50 flex flex-col items-center justify-center p-6 text-center gap-2">
                      <Layers className="text-slate-300" size={32} />
                      <p className="text-xs font-bold text-slate-700">No Image Uploaded</p>
                      <p className="text-[11px] text-slate-500 max-w-xs leading-relaxed font-semibold">
                        This page has no attached canvas file. Upload an asset under the "Files" tab or attach a file to begin visual editing.
                      </p>
                    </div>
                  )}
                </div>

                {/* Annotation Controls Panel (2/5 cols) */}
                <div className="md:col-span-2 space-y-4">
                  <div className="flex items-center justify-between border-b border-slate-100 pb-2">
                    <h3 className="text-[11px] font-bold text-slate-500 uppercase tracking-wider">Page Notes</h3>
                    {imageUrl && (
                      <button
                        onClick={() => {
                          setShowAnnotationForm(!showAnnotationForm);
                          setCurrentBox(null);
                        }}
                        className="text-[10px] font-bold text-indigo-600 hover:text-indigo-800 transition-colors uppercase tracking-wider"
                      >
                        {showAnnotationForm ? 'Cancel' : '+ Add Note'}
                      </button>
                    )}
                  </div>

                  {/* Add Annotation Form */}
                  {showAnnotationForm && (
                    <div className="p-4 bg-slate-900 border border-slate-800 rounded-xl space-y-3 animate-in slide-in-from-top-2 duration-200 text-slate-200">
                      <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-wider font-mono">
                        {currentBox ? 'Selection Coordinates Captured' : 'Global Page Note'}
                      </p>

                      <div>
                        <label className="text-[10px] font-bold text-slate-400 block mb-1 uppercase tracking-wider">
                          Type
                        </label>
                        <select
                          value={annotationType}
                          onChange={(e) => setAnnotationType(e.target.value as AnnotationType)}
                          className="w-full text-xs font-semibold bg-slate-950 border border-slate-800 rounded-lg px-2.5 py-1.5 focus:outline-none focus:border-indigo-500"
                        >
                          <option value="comment">💬 Comment</option>
                          <option value="highlight">🔆 Highlight</option>
                          <option value="error">❌ Error</option>
                          <option value="correction">✏️ Correction</option>
                        </select>
                      </div>

                      <div>
                        <label className="text-[10px] font-bold text-slate-400 block mb-1 uppercase tracking-wider">
                          Description
                        </label>
                        <textarea
                          value={annotationText}
                          onChange={(e) => setAnnotationText(e.target.value)}
                          placeholder="What needs to be done here?"
                          className="w-full text-xs bg-slate-950 border border-slate-800 rounded-lg px-2.5 py-2 focus:outline-none focus:border-indigo-500 resize-none h-20 text-slate-100"
                        />
                      </div>

                      <button
                        onClick={handleAddAnnotation}
                        disabled={annotationSubmitting || !annotationText.trim()}
                        className="w-full text-xs font-bold text-white bg-indigo-750 hover:bg-indigo-850 disabled:opacity-50 px-3 py-2 rounded-lg transition-colors shadow-md"
                      >
                        {annotationSubmitting ? 'Saving...' : 'Save Note'}
                      </button>
                    </div>
                  )}

                  {/* Annotations List */}
                  <div className="space-y-2">
                    {annotationsLoading ? (
                      <div className="flex items-center justify-center gap-2 p-6">
                        <Loader2 className="animate-spin text-slate-400" size={16} />
                        <span className="text-xs text-slate-500">Loading notes...</span>
                      </div>
                    ) : annotations.length === 0 ? (
                      <div className="p-6 text-center text-slate-400 text-xs border border-slate-100 bg-slate-50/30 rounded-xl font-semibold">
                        <MessageSquare size={20} className="mx-auto mb-2 text-slate-300" />
                        No annotations yet. Define boxes on canvas or add comments.
                      </div>
                    ) : (
                      <div className="space-y-2 max-h-[400px] overflow-y-auto pr-1">
                        {annotations.map((annotation: AnnotationResponse) => (
                          <div
                            key={annotation.id}
                            className={`p-3.5 rounded-xl border flex items-start justify-between gap-3 shadow-sm transition-all hover:shadow ${getAnnotationTypeColor(
                              (annotation.type || 'comment') as AnnotationType
                            )}`}
                          >
                            <div className="flex items-start gap-2.5 flex-1 min-w-0">
                              <div className="mt-0.5 shrink-0">
                                {getAnnotationTypeIcon((annotation.type || 'comment') as AnnotationType)}
                              </div>
                              <div className="flex-1 text-xs min-w-0">
                                <div className="flex items-center justify-between mb-0.5">
                                  <p className="font-extrabold capitalize leading-none">{annotation.type || 'Comment'}</p>
                                  {annotation.coordinatesJson && (
                                    <span className="text-[9px] font-mono font-bold bg-slate-950/5 px-1.5 py-0.5 rounded leading-none">
                                      Coord
                                    </span>
                                  )}
                                </div>
                                <p className="leading-relaxed font-medium break-words text-slate-700 mt-1">
                                  {annotation.description || annotation.notes || 'No description provided.'}
                                </p>
                                {annotation.createdAt && (
                                  <p className="text-[9px] font-semibold opacity-65 mt-1.5 font-mono">
                                    {new Date(annotation.createdAt).toLocaleDateString()}
                                  </p>
                                )}
                              </div>
                            </div>
                            <button
                              onClick={() => handleDeleteAnnotation(annotation.id)}
                              className="text-slate-400 hover:text-rose-600 transition-colors shrink-0 p-0.5 hover:bg-white rounded-md border border-transparent hover:border-slate-100"
                            >
                              <X size={13} />
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ) : (
              <div className="rounded-2xl border border-slate-200 bg-white p-8 text-center shadow-sm flex flex-col items-center justify-center min-h-[350px]">
                <div className="h-14 w-14 bg-indigo-50 border border-indigo-100 text-indigo-700 rounded-full flex items-center justify-center mb-4">
                  <Eye size={24} />
                </div>
                <h3 className="text-base font-bold text-slate-800">Select a Page</h3>
                <p className="text-xs text-slate-500 font-semibold mt-1 max-w-sm">
                  Choose a page from the left-hand sidebar list to inspect annotations, review coordinate boundaries, or write revisions.
                </p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { 
  BookOpen, Plus, Send, RefreshCw, AlertCircle, CheckCircle2, 
  XCircle, ChevronDown, Tag, Clock, TrendingUp, Sparkles
} from 'lucide-react';
import { mangaApi } from '@/services/manga-api';
import { SeriesResponse } from '@/types/manga';

const SERIES_STATUS_STYLE: Record<string, string> = {
  Draft:    'bg-slate-500/10 text-slate-400 border-slate-500/20',
  Submitted: 'bg-amber-500/10 text-amber-400 border-amber-500/20',
  Approved:  'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
  Ongoing:   'bg-indigo-500/10 text-indigo-400 border-indigo-500/20',
  Hiatus:    'bg-orange-500/10 text-orange-400 border-orange-500/20',
  Cancelled: 'bg-rose-500/10 text-rose-400 border-rose-500/20',
  Completed: 'bg-teal-500/10 text-teal-400 border-teal-500/20',
  RevisionRequested: 'bg-purple-500/10 text-purple-400 border-purple-500/20',
  Rejected:  'bg-rose-500/10 text-rose-300 border-rose-500/20',
};

interface Props {
  seriesError: string | null;
  seriesLoading: boolean;
  series: SeriesResponse[];
  fetchSeries: () => void;
  triggerModal: (title: string, content: string) => void;
}

export default function MangakaSeriesTab({
  seriesError,
  seriesLoading,
  series,
  fetchSeries,
  triggerModal,
}: Props) {
  const [showCreateForm, setShowCreateForm] = useState(false);

  // Studio creation
  const [studioName, setStudioName] = useState('');
  const [studioDesc, setStudioDesc] = useState('');
  const [studios, setStudios] = useState<{ id: string; name: string }[]>([]);
  const [studiosLoaded, setStudiosLoaded] = useState(false);

  // Series creation
  const [selectedStudioId, setSelectedStudioId] = useState('');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [genre, setGenre] = useState('');

  // Notifications
  const [success, setSuccess] = useState<string | null>(null);
  const [formError, setFormError] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  const flash = (msg: string) => {
    setSuccess(msg);
    setTimeout(() => setSuccess(null), 4000);
  };

  const loadStudios = async () => {
    if (studiosLoaded) return;
    try {
      const r = await mangaApi.getMyStudios();
      if (r.data.success) {
        setStudios((r.data.data ?? []).map((s: { id: string; name: string }) => ({ id: s.id, name: s.name })));
        setStudiosLoaded(true);
      }
    } catch {
      // ignore
    }
  };

  const handleOpenForm = async () => {
    setShowCreateForm(v => !v);
    if (!studiosLoaded) await loadStudios();
  };

  const handleCreateStudio = async () => {
    if (!studioName.trim()) return;
    setActionLoading('studio');
    setFormError(null);
    try {
      const r = await mangaApi.createStudio({ name: studioName.trim(), description: studioDesc.trim() || undefined });
      if (r.data.success && r.data.data) {
        const newStudio = r.data.data;
        setStudios(prev => [...prev, { id: newStudio.id, name: newStudio.name }]);
        setSelectedStudioId(newStudio.id);
        setStudioName(''); setStudioDesc('');
        flash(`Studio "${newStudio.name}" created.`);
      } else {
        setFormError(r.data.message || 'Failed to create studio.');
      }
    } catch (e: unknown) {
      const err = e as { response?: { data?: { message?: string } } };
      setFormError(err.response?.data?.message || 'Studio creation failed.');
    } finally {
      setActionLoading(null);
    }
  };

  const handleCreateSeries = async () => {
    if (!selectedStudioId || !title.trim()) return;
    setActionLoading('series');
    setFormError(null);
    try {
      const r = await mangaApi.createSeries({
        studioId: selectedStudioId,
        title: title.trim(),
        description: description.trim() || undefined,
        genre: genre.trim() || undefined,
      });
      if (r.data.success) {
        setTitle(''); setDescription(''); setGenre('');
        setShowCreateForm(false);
        flash('Series created successfully! You can now create chapters and submit for review.');
        fetchSeries();
      } else {
        setFormError(r.data.message || 'Failed to create series.');
      }
    } catch (e: unknown) {
      const err = e as { response?: { data?: { message?: string } } };
      setFormError(err.response?.data?.message || 'Series creation failed.');
    } finally {
      setActionLoading(null);
    }
  };

  const handleSubmitProposal = async (seriesId: string, seriesTitle: string) => {
    setActionLoading(seriesId);
    setFormError(null);
    try {
      const r = await mangaApi.submitProposal(seriesId);
      if (r.data.success) {
        flash(`Series "${seriesTitle}" submitted for editorial board review.`);
        fetchSeries();
      } else {
        setFormError(r.data.message || 'Could not submit proposal.');
      }
    } catch (e: unknown) {
      const err = e as { response?: { data?: { message?: string } } };
      setFormError(err.response?.data?.message || 'Proposal submission failed.');
    } finally {
      setActionLoading(null);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl font-bold text-slate-100">My Series</h1>
          <p className="text-xs text-slate-500 font-medium mt-0.5">
            Create and manage your manga series. Submit proposals to the Editorial Board for approval.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={fetchSeries}
            disabled={seriesLoading}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-slate-400 hover:text-slate-200 bg-slate-800/40 hover:bg-slate-800 border border-slate-700/50 rounded-lg transition-colors disabled:opacity-50"
          >
            <RefreshCw size={12} className={seriesLoading ? 'animate-spin' : ''} />
            Refresh
          </button>
          <button
            onClick={() => void handleOpenForm()}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg transition-colors shadow-sm"
          >
            <Plus size={13} />
            {showCreateForm ? 'Cancel' : 'New Series'}
          </button>
        </div>
      </div>

      {/* Notifications */}
      {(seriesError || formError) && (
        <div className="flex items-center gap-2 p-3 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-xl text-xs font-semibold">
          <AlertCircle size={13} className="shrink-0" />
          {seriesError || formError}
          <button onClick={() => setFormError(null)} className="ml-auto"><XCircle size={13} /></button>
        </div>
      )}
      {success && (
        <div className="flex items-center gap-2 p-3 bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 rounded-xl text-xs font-semibold">
          <CheckCircle2 size={13} className="shrink-0" />
          {success}
        </div>
      )}

      {/* Create Series Form */}
      {showCreateForm && (
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-5 space-y-5">
          <h3 className="text-sm font-bold text-slate-200 flex items-center gap-2">
            <Sparkles size={14} className="text-indigo-400" />
            Create New Series
          </h3>

          {/* Studio selection or creation */}
          <div className="space-y-3">
            <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider">Studio</label>
            {studios.length > 0 ? (
              <div className="relative">
                <select
                  value={selectedStudioId}
                  onChange={(e) => setSelectedStudioId(e.target.value)}
                  className="w-full appearance-none bg-slate-950 border border-slate-800 rounded-lg py-2 pl-3 pr-8 text-xs text-slate-300 font-semibold focus:outline-none focus:border-indigo-500 transition-colors"
                >
                  <option value="">— Select Studio —</option>
                  {studios.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
                <ChevronDown size={12} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
              </div>
            ) : null}

            {/* Inline studio creation */}
            <div className="p-3 bg-slate-950/60 border border-slate-800/60 rounded-lg space-y-2">
              <p className="text-[10px] font-bold text-slate-600 uppercase tracking-wider">Or create a new studio:</p>
              <div className="flex gap-2">
                <input
                  type="text"
                  placeholder="Studio name"
                  value={studioName}
                  onChange={(e) => setStudioName(e.target.value)}
                  className="flex-1 bg-slate-900 border border-slate-800 rounded-lg py-1.5 px-3 text-xs text-slate-300 font-semibold placeholder-slate-600 focus:outline-none focus:border-indigo-500 transition-colors"
                />
                <input
                  type="text"
                  placeholder="Description (optional)"
                  value={studioDesc}
                  onChange={(e) => setStudioDesc(e.target.value)}
                  className="flex-1 bg-slate-900 border border-slate-800 rounded-lg py-1.5 px-3 text-xs text-slate-300 font-semibold placeholder-slate-600 focus:outline-none focus:border-indigo-500 transition-colors"
                />
                <button
                  onClick={() => void handleCreateStudio()}
                  disabled={!studioName.trim() || actionLoading === 'studio'}
                  className="flex items-center gap-1 px-3 py-1.5 text-[10px] font-bold text-indigo-400 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 rounded-lg transition-colors disabled:opacity-50"
                >
                  {actionLoading === 'studio' ? <RefreshCw size={10} className="animate-spin" /> : <Plus size={10} />}
                  Create Studio
                </button>
              </div>
            </div>
          </div>

          {/* Series fields */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Title *</label>
              <input
                type="text"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="e.g. Blade of the Eternal Storm"
                className="w-full bg-slate-950 border border-slate-800 rounded-lg py-2 px-3 text-xs text-slate-300 font-semibold placeholder-slate-600 focus:outline-none focus:border-indigo-500 transition-colors"
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Genre</label>
              <div className="relative">
                <select
                  value={genre}
                  onChange={(e) => setGenre(e.target.value)}
                  className="w-full appearance-none bg-slate-950 border border-slate-800 rounded-lg py-2 pl-3 pr-8 text-xs text-slate-300 font-semibold focus:outline-none focus:border-indigo-500 transition-colors"
                >
                  <option value="">— Select Genre —</option>
                  {['Action','Adventure','Comedy','Drama','Fantasy','Horror','Mystery','Romance','Sci-Fi','Slice of Life','Sports','Supernatural','Thriller'].map(g => (
                    <option key={g} value={g}>{g}</option>
                  ))}
                </select>
                <ChevronDown size={12} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
              </div>
            </div>
            <div className="md:col-span-2">
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Description</label>
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Brief synopsis and concept overview for editorial board review…"
                rows={3}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg py-2 px-3 text-xs text-slate-300 font-semibold placeholder-slate-600 focus:outline-none focus:border-indigo-500 transition-colors resize-none"
              />
            </div>
          </div>

          <div className="flex justify-end">
            <button
              onClick={() => void handleCreateSeries()}
              disabled={!selectedStudioId || !title.trim() || actionLoading === 'series'}
              className="flex items-center gap-1.5 px-4 py-2 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg transition-colors disabled:opacity-40 disabled:cursor-not-allowed shadow-sm"
            >
              {actionLoading === 'series' ? <RefreshCw size={12} className="animate-spin" /> : <BookOpen size={12} />}
              Create Series
            </button>
          </div>
        </div>
      )}

      {/* Series List */}
      {seriesLoading ? (
        <div className="p-8 text-center">
          <RefreshCw size={18} className="animate-spin text-indigo-500 mx-auto mb-2" />
          <p className="text-xs text-slate-500 font-semibold">Loading series…</p>
        </div>
      ) : series.length === 0 ? (
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-10 text-center">
          <BookOpen size={28} className="text-slate-700 mx-auto mb-3" />
          <p className="text-sm font-semibold text-slate-600">No series yet.</p>
          <p className="text-xs text-slate-700 mt-1">Click "New Series" to create your first manga series.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {series.map((item) => {
            const statusStr = typeof item.status === 'number'
              ? ['','Draft','Submitted','Approved','Ongoing','Hiatus','Cancelled','Completed','RevisionRequested','Rejected'][item.status] ?? String(item.status)
              : String(item.status);
            const statusStyle = SERIES_STATUS_STYLE[statusStr] ?? 'bg-slate-500/10 text-slate-400 border-slate-500/20';
            const isDraft = statusStr === 'Draft' || item.status === 1;

            return (
              <div key={item.id} className="bg-slate-900 border border-slate-800 rounded-xl p-4 flex flex-col gap-3 hover:border-slate-700 transition-colors">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <h3 className="font-bold text-slate-200 text-sm truncate">{item.title}</h3>
                    <p className="text-[10px] text-slate-500 font-semibold mt-0.5 truncate">{item.description || 'No description'}</p>
                  </div>
                  <span className={`shrink-0 px-2 py-0.5 rounded-full text-[9px] font-bold border ${statusStyle}`}>
                    {statusStr}
                  </span>
                </div>

                <div className="flex flex-wrap gap-3 text-[10px] text-slate-600 font-semibold">
                  {item.genre && (
                    <span className="flex items-center gap-1"><Tag size={9} />{item.genre}</span>
                  )}
                  {item.updatedAt && (
                    <span className="flex items-center gap-1">
                      <Clock size={9} />Updated {new Date(item.updatedAt).toLocaleDateString()}
                    </span>
                  )}
                </div>

                {/* Actions */}
                {isDraft && (
                  <div className="pt-1 border-t border-slate-800">
                    <button
                      onClick={() => void handleSubmitProposal(item.id, item.title)}
                      disabled={actionLoading === item.id}
                      className="w-full flex items-center justify-center gap-1.5 py-2 text-[10px] font-bold text-amber-400 bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/20 rounded-lg transition-colors disabled:opacity-50"
                    >
                      {actionLoading === item.id ? <RefreshCw size={10} className="animate-spin" /> : <Send size={10} />}
                      Submit Proposal to Editorial Board
                    </button>
                  </div>
                )}

                {statusStr === 'RevisionRequested' && (
                  <div className="pt-1 border-t border-slate-800">
                    <div className="flex items-center gap-1.5 text-[10px] text-purple-400 font-semibold">
                      <TrendingUp size={10} />
                      Revision requested — update your series then resubmit.
                    </div>
                  </div>
                )}

                {statusStr === 'Approved' && (
                  <div className="pt-1 border-t border-slate-800">
                    <div className="flex items-center gap-1.5 text-[10px] text-emerald-400 font-semibold">
                      <CheckCircle2 size={10} />
                      Approved! You can now create chapters.
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import {
  CheckSquare, Plus, RefreshCw, AlertCircle, ChevronDown,
  User, Clock, Tag, CheckCircle2, RotateCcw, Send, XCircle
} from 'lucide-react';
import { authApi, AssistantDirectoryItem } from '@/services/auth-api';
import { mangaApi } from '@/services/manga-api';
import { fileApi } from '@/services/file-api';
import {
  ChapterResponse,
  CreateTaskRequest,
  PageResponse,
  AnnotationResponse,
  SeriesResponse,
  TaskPriority,
  TaskResponse,
  TaskStatus,
} from '@/types/manga';
import { isValidNonEmptyGuid } from '@/lib/guid';

interface MangakaTasksTabProps {
  triggerModal: (title: string, content: string) => void;
}

const TASK_STATUS_STYLE: Record<number, string> = {
  [TaskStatus.Todo]:             'bg-slate-500/10 text-slate-400 border-slate-500/20',
  [TaskStatus.InProgress]:       'bg-indigo-500/10 text-indigo-400 border-indigo-500/20',
  [TaskStatus.Submitted]:        'bg-amber-500/10 text-amber-400 border-amber-500/20',
  [TaskStatus.Approved]:         'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
  [TaskStatus.RevisionRequired]: 'bg-rose-500/10 text-rose-400 border-rose-500/20',
};

const TASK_STATUS_LABEL: Record<number, string> = {
  [TaskStatus.Todo]:             'Todo',
  [TaskStatus.InProgress]:       'In Progress',
  [TaskStatus.Submitted]:        'Submitted',
  [TaskStatus.Approved]:         'Approved',
  [TaskStatus.RevisionRequired]: 'Revision Required',
};

export default function MangakaTasksTab({ triggerModal }: MangakaTasksTabProps) {
  // Hierarchical data
  const [series, setSeries]           = useState<SeriesResponse[]>([]);
  const [chapters, setChapters]       = useState<ChapterResponse[]>([]);
  const [pages, setPages]             = useState<PageResponse[]>([]);
  const [annotations, setAnnotations] = useState<AnnotationResponse[]>([]);
  const [assistants, setAssistants]   = useState<AssistantDirectoryItem[]>([]);
  const [tasks, setTasks]             = useState<TaskResponse[]>([]);

  // Selections
  const [seriesId,         setSeriesId]     = useState('');
  const [chapterId,        setChapterId]    = useState('');
  const [pageId,           setPageId]       = useState('');
  const [annotationId,     setAnnotationId] = useState('');
  const [assignedToUserId, setAssigned]     = useState('');

  // Form
  const [title,  setTitle]  = useState('');
  const [reason, setReason] = useState('');
  const [revisionTargetId, setRevisionTargetId] = useState<string | null>(null);

  // UI state
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  const flash = (msg: string) => {
    setSuccess(msg);
    setTimeout(() => setSuccess(null), 4000);
  };

  const refresh = async () => {
    setLoading(true);
    try {
      const r = await mangaApi.getMyTasks();
      if (r.data.success) setTasks(r.data.data ?? []);
      else throw new Error(r.data.message);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Load failed');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void Promise.all([mangaApi.getSeries(), authApi.getAssistants()])
      .then(async ([s, a]) => {
        if (s.data.success) setSeries(s.data.data ?? []);
        if (a.data.success) setAssistants(a.data.data ?? []);
        await refresh();
      })
      .catch((e) => setError(e instanceof Error ? e.message : 'Load failed'));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const create = async () => {
    if (!isValidNonEmptyGuid(pageId) || !isValidNonEmptyGuid(annotationId) ||
        !isValidNonEmptyGuid(assignedToUserId) || !title.trim()) return;

    setActionLoading('create');
    setError(null);
    try {
      const r = await mangaApi.createTask({
        pageId, annotationId, assignedToUserId,
        title: title.trim(),
        priority: TaskPriority.Medium,
      } as CreateTaskRequest);
      if (!r.data.success) throw new Error(r.data.message);
      setTitle(''); setAnnotationId(''); setShowCreateForm(false);
      flash('Task created and assigned successfully.');
      await refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Create failed');
    } finally {
      setActionLoading(null);
    }
  };

  const approve = async (id: string) => {
    setActionLoading(id);
    setError(null);
    try {
      const r = await mangaApi.approveTask(id);
      if (!r.data.success) throw new Error(r.data.message);
      flash('Task approved successfully.');
      await refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Approve failed');
    } finally {
      setActionLoading(null);
    }
  };

  const revision = async (id: string) => {
    if (!reason.trim()) return;
    setActionLoading(id);
    setError(null);
    try {
      const r = await mangaApi.requestTaskRevision(id, { reason: reason.trim() });
      if (!r.data.success) throw new Error(r.data.message);
      setReason(''); setRevisionTargetId(null);
      flash('Revision requested.');
      await refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Revision failed');
    } finally {
      setActionLoading(null);
    }
  };

  const isFormValid = isValidNonEmptyGuid(pageId) && isValidNonEmptyGuid(annotationId) &&
                      isValidNonEmptyGuid(assignedToUserId) && title.trim().length > 0;

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl font-bold text-slate-100">Task Management</h1>
          <p className="text-xs text-slate-500 font-medium mt-0.5">
            Assign tasks to assistants from page annotations. Review and approve submitted work.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => void refresh()}
            disabled={loading}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-slate-400 hover:text-slate-200 bg-slate-800/40 hover:bg-slate-800 border border-slate-700/50 rounded-lg transition-colors disabled:opacity-50"
          >
            <RefreshCw size={12} className={loading ? 'animate-spin' : ''} />
            Refresh
          </button>
          <button
            onClick={() => setShowCreateForm(v => !v)}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg transition-colors shadow-sm"
          >
            <Plus size={13} />
            {showCreateForm ? 'Cancel' : 'Assign New Task'}
          </button>
        </div>
      </div>

      {/* Notifications */}
      {error && (
        <div className="flex items-center gap-2 p-3 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-xl text-xs font-semibold">
          <AlertCircle size={13} className="shrink-0" />
          {error}
          <button onClick={() => setError(null)} className="ml-auto"><XCircle size={13} /></button>
        </div>
      )}
      {success && (
        <div className="flex items-center gap-2 p-3 bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 rounded-xl text-xs font-semibold">
          <CheckCircle2 size={13} className="shrink-0" />
          {success}
        </div>
      )}

      {/* Create Task Form */}
      {showCreateForm && (
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-5 space-y-4">
          <h3 className="text-sm font-bold text-slate-200 flex items-center gap-2">
            <Plus size={14} className="text-indigo-400" />
            Assign New Task to Assistant
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {/* Series */}
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Series</label>
              <div className="relative">
                <select
                  aria-label="Series"
                  value={seriesId}
                  onChange={async (e) => {
                    const id = e.target.value;
                    setSeriesId(id); setChapterId(''); setPageId(''); setAnnotationId('');
                    setChapters([]); setPages([]); setAnnotations([]);
                    if (id) {
                      const r = await mangaApi.getChapters(id);
                      if (r.data.success) setChapters(r.data.data ?? []);
                    }
                  }}
                  className="w-full appearance-none bg-slate-950 border border-slate-800 rounded-lg py-2 pl-3 pr-8 text-xs text-slate-300 font-semibold focus:outline-none focus:border-indigo-500 transition-colors"
                >
                  <option value="">— Select Series —</option>
                  {series.map(x => <option key={x.id} value={x.id}>{x.title}</option>)}
                </select>
                <ChevronDown size={12} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
              </div>
            </div>

            {/* Chapter */}
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Chapter</label>
              <div className="relative">
                <select
                  aria-label="Chapter"
                  value={chapterId}
                  onChange={async (e) => {
                    const id = e.target.value;
                    setChapterId(id); setPageId(''); setAnnotationId('');
                    setPages([]); setAnnotations([]);
                    if (id) {
                      const r = await mangaApi.getPages(id);
                      if (r.data.success) setPages(r.data.data ?? []);
                    }
                  }}
                  disabled={!seriesId}
                  className="w-full appearance-none bg-slate-950 border border-slate-800 rounded-lg py-2 pl-3 pr-8 text-xs text-slate-300 font-semibold focus:outline-none focus:border-indigo-500 transition-colors disabled:opacity-40"
                >
                  <option value="">— Select Chapter —</option>
                  {chapters.map(x => <option key={x.id} value={x.id}>Ch.{x.chapterNumber}: {x.title || 'Untitled'}</option>)}
                </select>
                <ChevronDown size={12} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
              </div>
            </div>

            {/* Page */}
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Page</label>
              <div className="relative">
                <select
                  aria-label="Page"
                  value={pageId}
                  onChange={async (e) => {
                    const id = e.target.value;
                    setPageId(id); setAnnotationId(''); setAnnotations([]);
                    if (id) {
                      const r = await mangaApi.getPageAnnotations(id);
                      if (r.data.success) setAnnotations(r.data.data ?? []);
                    }
                  }}
                  disabled={!chapterId}
                  className="w-full appearance-none bg-slate-950 border border-slate-800 rounded-lg py-2 pl-3 pr-8 text-xs text-slate-300 font-semibold focus:outline-none focus:border-indigo-500 transition-colors disabled:opacity-40"
                >
                  <option value="">— Select Page —</option>
                  {pages.map(x => <option key={x.id} value={x.id}>Page {x.pageNumber}</option>)}
                </select>
                <ChevronDown size={12} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
              </div>
            </div>

            {/* Annotation */}
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Annotation Region</label>
              <div className="relative">
                <select
                  aria-label="Annotation"
                  value={annotationId}
                  onChange={(e) => setAnnotationId(e.target.value)}
                  disabled={!pageId}
                  className="w-full appearance-none bg-slate-950 border border-slate-800 rounded-lg py-2 pl-3 pr-8 text-xs text-slate-300 font-semibold focus:outline-none focus:border-indigo-500 transition-colors disabled:opacity-40"
                >
                  <option value="">— Select Annotation —</option>
                  {annotations.map(x => (
                    <option key={x.id} value={x.id}>[{x.type}] {x.description || x.notes || 'Region'}</option>
                  ))}
                </select>
                <ChevronDown size={12} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
              </div>
            </div>

            {/* Assign to */}
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Assign To (Assistant)</label>
              <div className="relative">
                <select
                  aria-label="Assistant"
                  value={assignedToUserId}
                  onChange={(e) => setAssigned(e.target.value)}
                  className="w-full appearance-none bg-slate-950 border border-slate-800 rounded-lg py-2 pl-3 pr-8 text-xs text-slate-300 font-semibold focus:outline-none focus:border-indigo-500 transition-colors"
                >
                  <option value="">— Select Assistant —</option>
                  {assistants.map(x => <option key={x.id} value={x.id}>{x.fullName}</option>)}
                </select>
                <ChevronDown size={12} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
              </div>
            </div>

            {/* Task Title */}
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Task Title</label>
              <input
                aria-label="Task title"
                type="text"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="e.g. Translate panel text, Ink background…"
                className="w-full bg-slate-950 border border-slate-800 rounded-lg py-2 px-3 text-xs text-slate-300 font-semibold placeholder-slate-600 focus:outline-none focus:border-indigo-500 transition-colors"
              />
            </div>
          </div>

          <div className="flex justify-end pt-2">
            <button
              onClick={() => void create()}
              disabled={!isFormValid || actionLoading === 'create'}
              className="flex items-center gap-1.5 px-4 py-2 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg transition-colors disabled:opacity-40 disabled:cursor-not-allowed shadow-sm"
            >
              {actionLoading === 'create' ? (
                <RefreshCw size={12} className="animate-spin" />
              ) : (
                <Send size={12} />
              )}
              Create & Assign Task
            </button>
          </div>
        </div>
      )}

      {/* Tasks List */}
      <div className="bg-slate-900 border border-slate-800 rounded-xl overflow-hidden">
        <div className="px-4 py-3 border-b border-slate-800 flex items-center justify-between">
          <h2 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
            <CheckSquare size={12} className="text-indigo-400" />
            All Tasks — Review & Manage
          </h2>
          <span className="text-[10px] font-bold text-slate-600">{tasks.length} task(s)</span>
        </div>

        {loading ? (
          <div className="p-8 text-center">
            <RefreshCw size={18} className="animate-spin text-indigo-500 mx-auto mb-2" />
            <p className="text-xs text-slate-500 font-semibold">Loading tasks…</p>
          </div>
        ) : tasks.length === 0 ? (
          <div className="p-8 text-center">
            <CheckSquare size={24} className="text-slate-700 mx-auto mb-3" />
            <p className="text-sm font-semibold text-slate-600">No tasks yet.</p>
            <p className="text-xs text-slate-700 mt-1">Use the Page Editor to create annotations, then assign tasks to assistants.</p>
          </div>
        ) : (
          <div className="divide-y divide-slate-800/60">
            {tasks.map(task => {
              const statusStyle = TASK_STATUS_STYLE[task.status] ?? 'bg-slate-500/10 text-slate-400 border-slate-500/20';
              const statusLabel = TASK_STATUS_LABEL[task.status] ?? String(task.status);
              const isSubmitted = task.status === TaskStatus.Submitted;

              return (
                <div key={task.id} className="p-4 hover:bg-slate-850/30 transition-colors">
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <h3 className="text-sm font-bold text-slate-200 truncate">{task.title}</h3>
                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[9px] font-bold border ${statusStyle}`}>
                          {statusLabel}
                        </span>
                      </div>

                      {/* Meta info */}
                      <div className="flex flex-wrap items-center gap-3 mt-1.5 text-[10px] text-slate-600 font-semibold">
                        {task.assignedToUserId && (
                          <span className="flex items-center gap-1">
                            <User size={10} className="text-slate-700" />
                            Assistant assigned
                          </span>
                        )}
                        {task.deadline && (
                          <span className="flex items-center gap-1">
                            <Clock size={10} className="text-slate-700" />
                            {new Date(task.deadline).toLocaleDateString()}
                          </span>
                        )}
                        <span className="flex items-center gap-1">
                          <Tag size={10} className="text-slate-700" />
                          Priority: {task.priority ?? 'Normal'}
                        </span>
                      </div>

                      {/* Submission History */}
                      {task.submissionHistory && task.submissionHistory.length > 0 && (
                        <div className="mt-3 space-y-2 border border-slate-800/60 rounded-xl p-3 bg-slate-950/40">
                          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1">Submission History</p>
                          <div className="space-y-2 divide-y divide-slate-850">
                            {task.submissionHistory.map((sub, sIdx) => {
                              const versionNum = (task.submissionHistory?.length ?? 0) - sIdx;
                              const isLatest = sIdx === 0;
                              return (
                                <div key={sub.id} className="pt-2 first:pt-0 space-y-1">
                                  <div className="flex items-center gap-2">
                                    <span className="text-[10px] font-bold text-indigo-400">Version {versionNum}</span>
                                    {isLatest && <span className="bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 px-1 py-0.5 rounded text-[8px] font-black uppercase">Latest</span>}
                                    <span className="text-[9px] text-slate-600 font-semibold">
                                      {new Date(sub.submittedAt).toLocaleString()}
                                    </span>
                                    <span className="text-[9px] font-bold text-slate-500">
                                      by Assistant {sub.submittedByUserId.slice(0, 8)}
                                    </span>
                                  </div>
                                  {sub.note && <p className="text-xs text-slate-300 italic bg-slate-900/40 p-1.5 rounded border border-slate-850">&quot;{sub.note}&quot;</p>}
                                  {sub.fileId && (
                                    <div className="flex items-center justify-between pt-1">
                                      <span className="text-[9px] text-slate-600 font-mono">File: {sub.fileId.slice(0, 8)}...</span>
                                      <button
                                        onClick={async () => {
                                          try {
                                            const dl = await fileApi.downloadFile(sub.fileId!);
                                            if (!(dl.data instanceof Blob)) throw new Error('Download failed');
                                            const url = window.URL.createObjectURL(dl.data);
                                            const link = document.createElement('a');
                                            link.href = url;
                                            link.download = `submission-v${versionNum}.png`;
                                            link.click();
                                            window.URL.revokeObjectURL(url);
                                          } catch (err) {
                                            triggerModal('Download Error', 'Could not download the submission file.');
                                          }
                                        }}
                                        className="inline-flex items-center gap-1 text-[9px] text-indigo-450 hover:text-indigo-400 font-bold"
                                      >
                                        Download File
                                      </button>
                                    </div>
                                  )}
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      )}
                    </div>

                    {/* Action buttons */}
                    {isSubmitted && (
                      <div className="flex flex-col gap-2 shrink-0">
                        <button
                          onClick={() => void approve(task.id)}
                          disabled={actionLoading === task.id}
                          className="flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-bold text-emerald-400 bg-emerald-500/10 hover:bg-emerald-500/20 border border-emerald-500/20 rounded-lg transition-colors disabled:opacity-50"
                        >
                          {actionLoading === task.id ? <RefreshCw size={10} className="animate-spin" /> : <CheckCircle2 size={10} />}
                          Approve
                        </button>
                        <button
                          onClick={() => setRevisionTargetId(revisionTargetId === task.id ? null : task.id)}
                          disabled={actionLoading === task.id}
                          className="flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-bold text-amber-400 bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/20 rounded-lg transition-colors disabled:opacity-50"
                        >
                          <RotateCcw size={10} />
                          Revise
                        </button>
                      </div>
                    )}
                  </div>

                  {/* Revision reason input (inline) */}
                  {isSubmitted && revisionTargetId === task.id && (
                    <div className="mt-3 p-3 bg-slate-950/60 rounded-lg border border-amber-500/20 space-y-2">
                      <label className="block text-[10px] font-bold text-amber-400 uppercase tracking-wider">Revision Reason</label>
                      <input
                        aria-label="Revision reason"
                        type="text"
                        value={reason}
                        onChange={(e) => setReason(e.target.value)}
                        placeholder="Explain what needs to be fixed…"
                        className="w-full bg-slate-900 border border-slate-800 rounded-lg py-2 px-3 text-xs text-slate-300 font-semibold placeholder-slate-600 focus:outline-none focus:border-amber-500 transition-colors"
                      />
                      <div className="flex justify-end gap-2">
                        <button
                          onClick={() => { setRevisionTargetId(null); setReason(''); }}
                          className="px-3 py-1.5 text-[10px] font-bold text-slate-400 hover:text-slate-200 transition-colors"
                        >
                          Cancel
                        </button>
                        <button
                          onClick={() => void revision(task.id)}
                          disabled={!reason.trim() || actionLoading === task.id}
                          className="flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-bold text-amber-400 bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/20 rounded-lg transition-colors disabled:opacity-50"
                        >
                          {actionLoading === task.id ? <RefreshCw size={10} className="animate-spin" /> : <RotateCcw size={10} />}
                          Send Revision Request
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import StatusBadge from './StatusBadge';
import PriorityBadge from './PriorityBadge';
import { Eye, Edit3, MessageCircle } from 'lucide-react';
import { clsx } from 'clsx';

export interface TaskItem {
  id: string;
  taskName: string;
  page: string;
  assistant: string;
  status: string;
  priority: string;
  deadline: string;
  actionText: 'Review' | 'Open' | string;
}

interface TaskTableProps {
  tasks: TaskItem[];
  onAction?: (taskId: string, actionType: string) => void;
}

export default function TaskTable({ tasks, onAction }: TaskTableProps) {
  const handleActionClick = (taskId: string, actionText: string) => {
    if (onAction) {
      onAction(taskId, actionText);
    } else {
      alert(`Action "${actionText}" triggered for Task ID: ${taskId}`);
    }
  };

  return (
    <div className="bg-white border border-slate-100 rounded-xl shadow-[0_2px_8px_rgba(0,0,0,0.04)] overflow-hidden">
      {/* Table Header / Action Bar */}
      <div className="px-6 py-4 border-b border-slate-100 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 bg-slate-50/50">
        <div>
          <h3 className="font-bold text-slate-800 text-lg">Production Task Board</h3>
          <p className="text-xs text-slate-700 font-medium mt-0.5">
            Monitor and review background work assigned to studio assistants.
          </p>
        </div>
        <div className="flex gap-2">
          <select aria-label="Filter by page range" className="text-xs font-semibold text-slate-650 bg-white border border-slate-200 px-3 py-1.5 rounded-lg focus:outline-none focus:border-burgundy-500">
            <option>All Pages</option>
            <option>P01 - P10</option>
            <option>P11 - P20</option>
          </select>
          <select aria-label="Filter by status" className="text-xs font-semibold text-slate-650 bg-white border border-slate-200 px-3 py-1.5 rounded-lg focus:outline-none focus:border-burgundy-500">
            <option>All Statuses</option>
            <option>Submitted</option>
            <option>In Progress</option>
            <option>Revision Required</option>
          </select>
        </div>
      </div>

      {/* Main Table */}
      <div className="overflow-x-auto" tabIndex={0} role="region" aria-label="Production task board">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="border-b border-slate-100 bg-slate-50/40 text-slate-700 font-semibold text-xs uppercase tracking-wider">
              <th className="px-6 py-3.5">Task Description</th>
              <th className="px-6 py-3.5">Page</th>
              <th className="px-6 py-3.5">Assistant</th>
              <th className="px-6 py-3.5">Status</th>
              <th className="px-6 py-3.5">Priority</th>
              <th className="px-6 py-3.5">Deadline</th>
              <th className="px-6 py-3.5 text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100/80">
            {tasks.map((task) => {
              const isUrgent = task.priority.toLowerCase() === 'urgent';
              const isSubmitted = task.status.toLowerCase() === 'submitted';

              return (
                <tr 
                  key={task.id} 
                  className={clsx(
                    "hover:bg-slate-50/80 transition-colors duration-150 text-sm font-medium",
                    isUrgent && task.status.toLowerCase() === 'revision required' && "bg-rose-50/10"
                  )}
                >
                  <td className="px-6 py-4 text-slate-800">
                    <span className="font-bold">{task.taskName}</span>
                  </td>
                  <td className="px-6 py-4 text-slate-600 font-mono">
                    {task.page}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <div className="h-6 w-6 rounded-full bg-plum-50 border border-plum-150 flex items-center justify-center text-[10px] font-bold text-plum-700 uppercase">
                        {task.assistant.slice(0, 2)}
                      </div>
                      <span className="text-slate-700">{task.assistant}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <StatusBadge status={task.status} />
                  </td>
                  <td className="px-6 py-4">
                    <PriorityBadge priority={task.priority} />
                  </td>
                  <td className="px-6 py-4">
                    <span className={clsx(
                      "font-semibold text-xs px-2 py-0.5 rounded",
                      task.deadline.toLowerCase() === 'today' && "bg-burgundy-50 text-burgundy-800",
                      task.deadline.toLowerCase() === 'tomorrow' && "bg-amber-50 text-amber-800",
                      task.deadline.toLowerCase() === 'overdue' && "bg-rose-100 text-rose-800 font-bold",
                      !['today', 'tomorrow', 'overdue'].includes(task.deadline.toLowerCase()) && "text-slate-500"
                    )}>
                      {task.deadline}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button
                      onClick={() => handleActionClick(task.id, task.actionText)}
                      className={clsx(
                        "inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold shadow-sm transition-all duration-150",
                        task.actionText.toLowerCase() === 'review'
                          ? "bg-burgundy-800 hover:bg-burgundy-900 text-white active:bg-burgundy-950"
                          : "bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 active:bg-slate-100"
                      )}
                    >
                      {task.actionText.toLowerCase() === 'review' ? (
                        <>
                          <Eye size={12} />
                          <span>Review</span>
                        </>
                      ) : (
                        <>
                          <Edit3 size={12} />
                          <span>Open</span>
                        </>
                      )}
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Table Footer */}
      <div className="px-6 py-4 border-t border-slate-100 flex items-center justify-between text-xs text-slate-700 font-semibold bg-slate-50/20">
        <span>Showing {tasks.length} active assignments</span>
        <button className="text-burgundy-800 hover:text-burgundy-950 transition-colors">
          View All Studio Tasks →
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useRef, useState } from 'react';
import { useNotificationStore } from '@/store/notification-store';
import { useAuthStore } from '@/store/auth-store';
import { createSignalRConnection, startSignalRConnection, stopSignalRConnection } from '@/lib/signalr';
import { HubConnection } from '@microsoft/signalr';
import { 
  Bell, 
  Check, 
  AlertTriangle, 
  Clipboard, 
  FileCheck, 
  Mail, 
  CheckCheck,
  TrendingUp,
  Server,
  Trash2,
  RefreshCw,
  X
} from 'lucide-react';
import { useRouter } from 'next/navigation';
import { resolveNotificationRoute } from '@/lib/notification-router';
import { NotificationResponse, NotificationType } from '@/types/notification';

export default function NotificationDropdown() {
  const { 
    notifications, 
    unreadCount, 
    isLoading,
    error,
    fetchNotifications, 
    fetchUnreadCount, 
    markAsRead, 
    markAllAsRead,
    deleteNotification,
    addNotification,
    clearError,
    reconcileAfterReconnect,
  } = useNotificationStore();
  const accessToken = useAuthStore((state) => state.accessToken);
  const router = useRouter();
  const [isOpen, setIsOpen] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'connected' | 'disconnected' | 'reconnecting'>('disconnected');
  const dropdownRef = useRef<HTMLDivElement>(null);
  const connectionRef = useRef<HubConnection | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | undefined>(undefined);

  const handleNotificationClick = async (notification: NotificationResponse) => {
    if (notification.status === 1) {
      await markAsRead(notification.id);
    }
    setIsOpen(false);
    const targetRoute = resolveNotificationRoute(notification);
    router.push(targetRoute);
  };

  // Fetch notifications on mount
  useEffect(() => {
    fetchNotifications();
    fetchUnreadCount();
  }, [fetchNotifications, fetchUnreadCount]);

  // Set up SignalR with enhanced reconnection handling
  useEffect(() => {
    if (!accessToken) return;

    const connection = createSignalRConnection(() => useAuthStore.getState().accessToken || '');
    connectionRef.current = connection;

    // Backend may emit either name – register both to be safe
    const handleNotification = (notification: NotificationResponse) => {
      console.log('[SignalR] Received notification:', notification.id);
      addNotification(notification);
    };

     // Schedule reconnect with exponential backoff
    const scheduleReconnect = (connection: HubConnection) => {
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
    }
      reconnectTimeoutRef.current = setTimeout(() => {
        if (accessToken) {
        console.log('[SignalR] Attempting manual reconnect...');
        startSignalRConnection(connection).then((success) => {
          setConnectionStatus(success ? 'connected' : 'disconnected');
          });
        }
      }, 5000); // 5 second retry
    };

    // Event listeners for notifications
    connection.on('NotificationReceived', handleNotification);
    connection.on('ReceiveNotification', handleNotification);

    // Task update events (if backend broadcasts these via SignalR)
    connection.on('TaskStatusChanged', (taskData: any) => {
      console.log('[SignalR] Task status changed:', taskData);
      // Could trigger toast or invalidate queries here
    });

    // Editorial update events (if backend broadcasts these via SignalR)
    connection.on('EditorialDecisionMade', (editorialData: any) => {
      console.log('[SignalR] Editorial decision made:', editorialData);
      // Could trigger toast or invalidate queries here
    });

    // Connection state handlers
    connection.onreconnecting(() => {
      console.log('[SignalR] Attempting to reconnect...');
      setConnectionStatus('reconnecting');
    });

    connection.onreconnected(() => {
      console.log('[SignalR] Reconnected successfully, reconciling state...');
      setConnectionStatus('connected');
      // Reconcile state after reconnect
      reconcileAfterReconnect();
      // Refresh unread count
      fetchUnreadCount();
    });

    connection.onclose(() => {
      console.log('[SignalR] Connection closed');
      setConnectionStatus('disconnected');
      // Attempt reconnect with exponential backoff
      scheduleReconnect(connection);
    });

    startSignalRConnection(connection).then((success) => {
      setConnectionStatus(success ? 'connected' : 'disconnected');
    });

    // Cleanup function
    return () => {
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
      stopSignalRConnection(connection).catch((err) => {
        console.warn('[SignalR] Error during cleanup:', err);
      });
      connectionRef.current = null;
    };
  }, [accessToken, addNotification, reconcileAfterReconnect, fetchUnreadCount]);

 

  // Polling fallback when SignalR is unavailable
  useEffect(() => {
    if (connectionStatus === 'connected') return;

    const interval = setInterval(() => {
      console.log('[Notification] SignalR not connected. Fallback polling...');
      void fetchNotifications();
      void fetchUnreadCount();
    }, 15000);

    return () => clearInterval(interval);
  }, [connectionStatus, fetchNotifications, fetchUnreadCount]);

  // Click outside listener
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        console.log('[DEBUG] Click outside detected. Target:', event.target);
        setIsOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const getIcon = (type: NotificationType) => {
    switch (type) {
      case NotificationType.TaskAssigned:
        return <Clipboard className="h-4 w-4 text-sky-400" />;
      case NotificationType.TaskSubmitted:
        return <Clipboard className="h-4 w-4 text-yellow-400" />;
      case NotificationType.TaskApproved:
        return <Check className="h-4 w-4 text-emerald-400" />;
      case NotificationType.ChapterSubmittedForReview:
        return <FileCheck className="h-4 w-4 text-purple-400" />;
      case NotificationType.ChapterApproved:
        return <Check className="h-4 w-4 text-green-400" />;
      case NotificationType.RankingCalculated:
        return <TrendingUp className="h-4 w-4 text-pink-400" />;
      case NotificationType.CancellationWarning:
        return <AlertTriangle className="h-4 w-4 text-rose-500" />;
      case NotificationType.System:
        return <Server className="h-4 w-4 text-teal-400" />;
      default:
        return <Mail className="h-4 w-4 text-slate-400" />;
    }
  };

  const formatTime = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return date.toLocaleDateString();
  };

  return (
    <div className="relative" ref={dropdownRef}>
      {/* Bell Button with connection indicator */}
      <button
        id="bell-notification-btn"
        aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ''}`}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        onClick={() => {
          console.log('[DEBUG] Bell button clicked! Current isOpen state:', isOpen);
          setIsOpen(!isOpen);
        }}
        className="relative p-2 text-slate-400 hover:text-slate-200 rounded-lg hover:bg-slate-800/80 border border-transparent hover:border-slate-800/40 transition-all duration-200"
      >
        <Bell size={20} aria-hidden="true" />
        {unreadCount > 0 && (
          <span className="absolute top-0.5 right-0.5 h-4 min-w-4 px-1 flex items-center justify-center bg-indigo-600 text-[9px] font-bold text-white rounded-full border border-slate-900 shadow-md" aria-hidden="true">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
        {/* Connection status indicator */}
        <span aria-hidden="true" className={`absolute bottom-0.5 right-0.5 h-2 w-2 rounded-full border border-slate-900 ${
          connectionStatus === 'connected' ? 'bg-emerald-500' : 
          connectionStatus === 'reconnecting' ? 'bg-yellow-500 animate-pulse' : 
          'bg-slate-600'
        }`} />
      </button>

      {/* Dropdown Panel */}
      {isOpen && (
        <div id="notification-dropdown-container" role="dialog" aria-label="Notifications" className="absolute right-0 mt-2 w-80 md:w-96 rounded-xl bg-slate-900 border border-slate-800 shadow-2xl shadow-black/80 overflow-hidden z-50 transition-all animate-in fade-in slide-in-from-top-2 duration-200">
          {/* Header */}
          <div className="p-4 border-b border-slate-800 flex items-center justify-between bg-slate-900/80">
            <span className="font-semibold text-sm text-slate-200">Notifications</span>
            <div className="flex items-center gap-2">
              {/* Connection status text */}
              <span className={`text-[9px] font-mono px-2 py-0.5 rounded ${
                connectionStatus === 'connected' ? 'bg-emerald-500/10 text-emerald-400' :
                connectionStatus === 'reconnecting' ? 'bg-yellow-500/10 text-yellow-400' :
                'bg-slate-700/50 text-slate-500'
              }`}>
                {connectionStatus}
              </span>
              {/* Refresh button */}
              <button
                onClick={() => { clearError(); fetchNotifications(); }}
                className="p-1 text-slate-500 hover:text-slate-300 rounded-md hover:bg-slate-800/60 transition-colors"
                title="Refresh notifications"
              >
                <RefreshCw size={13} className={isLoading ? 'animate-spin' : ''} />
              </button>
              {unreadCount > 0 && (
                <button
                  onClick={markAllAsRead}
                  className="flex items-center gap-1 text-xs text-indigo-400 hover:text-indigo-300 font-medium transition-colors"
                >
                  <CheckCheck size={14} className="inline mr-0.5" />
                  Mark all read
                </button>
              )}
            </div>
          </div>

          {/* Error State */}
          {error && (
            <div className="p-3 bg-rose-500/10 border-b border-rose-500/20 flex items-start gap-2">
              <AlertTriangle size={14} className="text-rose-400 mt-0.5 shrink-0" />
              <p className="text-xs text-rose-300 flex-1">{error}</p>
              <button
                onClick={clearError}
                className="text-rose-400 hover:text-rose-200 transition-colors"
              >
                <X size={12} />
              </button>
            </div>
          )}

          {/* Loading State */}
          {isLoading && (
            <div className="p-4 text-center text-slate-500 text-xs">
              <div className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-indigo-500 border-t-transparent mb-1" />
              <p>Loading notifications…</p>
            </div>
          )}

          {/* List */}
          {!isLoading && (
            <div className="max-h-[350px] overflow-y-auto divide-y divide-slate-800/60 bg-slate-900/40">
              {notifications.length === 0 ? (
                <div className="p-8 text-center text-slate-500 flex flex-col items-center gap-2">
                  <Bell size={24} className="opacity-30 mb-1" />
                  <span className="text-sm font-medium">No notifications yet</span>
                  <span className="text-xs text-slate-600">We will notify you here when updates occur.</span>
                </div>
              ) : (
                notifications.map((notification) => (
                  <div
                    key={notification.id}
                    role="button"
                    tabIndex={0}
                    onClick={() => handleNotificationClick(notification)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        handleNotificationClick(notification);
                      }
                    }}
                    className={`p-4 transition-colors flex gap-3 cursor-pointer outline-none focus:bg-slate-800/60 ${
                      notification.status === 1 ? 'bg-indigo-600/5 hover:bg-indigo-600/10' : 'hover:bg-slate-800/30'
                    }`}
                  >
                    {/* Icon */}
                    <div className="h-8 w-8 rounded-lg bg-slate-800/80 border border-slate-700/60 flex items-center justify-center shrink-0">
                      {getIcon(notification.type)}
                    </div>

                    {/* Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-start mb-1 gap-2">
                        <span className={`text-xs font-semibold truncate ${
                          notification.status === 1 ? 'text-slate-200 font-bold' : 'text-slate-400 font-semibold'
                        }`}>
                          {notification.title}
                        </span>
                        <span className="text-[9px] text-slate-500 shrink-0 font-mono">
                          {formatTime(notification.createdAt)}
                        </span>
                      </div>
                      <p className={`text-xs leading-relaxed break-words ${
                        notification.status === 1 ? 'text-slate-350 font-medium' : 'text-slate-400'
                      }`}>
                        {notification.message}
                      </p>
                    </div>

                    {/* Actions */}
                    <div className="flex flex-col gap-1 self-center">
                      {notification.status === 1 && (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            markAsRead(notification.id);
                          }}
                          className="p-1 text-indigo-400 hover:text-indigo-300 hover:bg-indigo-500/10 rounded-md transition-all duration-150"
                          title="Mark as read"
                        >
                          <Check size={13} />
                        </button>
                      )}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          deleteNotification(notification.id);
                        }}
                        className="p-1 text-slate-600 hover:text-rose-400 hover:bg-rose-500/10 rounded-md transition-all duration-150"
                        title="Delete notification"
                      >
                        <Trash2 size={13} />
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useReader } from '@/hooks/useReader';
import { MessageCircle, Loader2, Trash2 } from 'lucide-react';

export default function CommentsTab() {
  const { addSeriesComment, getSeriesComments, updateComment, deleteComment } = useReader();
  const [selectedSeriesId, setSelectedSeriesId] = useState('');
  const [commentContent, setCommentContent] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { data: comments = [] } = selectedSeriesId ? getSeriesComments(selectedSeriesId) : { data: [] };

  const handleAddComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSeriesId.trim() || !commentContent.trim()) {
      alert('Please enter series ID and comment');
      return;
    }

    setIsSubmitting(true);
    try {
      await addSeriesComment.mutateAsync({
        seriesId: selectedSeriesId,
        request: { content: commentContent },
      });
      setCommentContent('');
      alert('Comment added successfully!');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteComment = async (id: string) => {
    if (confirm('Delete this comment?')) {
      await deleteComment.mutateAsync(id);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-slate-900 border border-slate-700 rounded-lg p-6">
        <h3 className="text-lg font-semibold text-slate-100 mb-4">Add Comment</h3>
        <form onSubmit={handleAddComment} className="space-y-4">
          <div>
            <label className="block text-sm text-slate-300 mb-2">Series ID</label>
            <input
              type="text"
