import React, { useState } from 'react';
import { useReader } from '@/hooks/useReader';
import { Clock, Loader2, Trash2, AlertCircle } from 'lucide-react';

export default function HistoryTab() {
  const { history, historyLoading, clearHistory } = useReader();
  const [isClearing, setIsClearing] = useState(false);

  const handleClearHistory = async () => {
    if (confirm('Clear all reading history? This cannot be undone.')) {
      setIsClearing(true);
      try {
        await clearHistory.mutateAsync();
      } finally {
        setIsClearing(false);
      }
    }
  };

  if (historyLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-slate-400" />
      </div>
    );
  }

  if (!history || history.length === 0) {
    return (
      <div className="text-center py-12">
        <Clock className="h-12 w-12 text-slate-600 mx-auto mb-4" />
        <p className="text-slate-400">No reading history yet. Start reading!</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex justify-end">
        <button
          onClick={handleClearHistory}
          disabled={isClearing}
          className="flex items-center gap-2 px-4 py-2 bg-red-900/20 text-red-400 border border-red-700 rounded-lg hover:bg-red-900/30 disabled:opacity-50 transition"
        >
          <Trash2 className="h-4 w-4" />
          Clear History
        </button>
      </div>

      <div className="space-y-3">
        {history.map((item, idx) => (
          <div
            key={idx}
            className="bg-slate-900 border border-slate-700 rounded-lg p-4 hover:border-slate-600 transition"
          >
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div>
                <p className="text-sm text-slate-400">Series ID</p>
                <p className="text-slate-200 font-medium text-sm truncate">{item.seriesId}</p>
              </div>
              <div>
                <p className="text-sm text-slate-400">Chapter ID</p>
                <p className="text-slate-200 font-medium text-sm truncate">{item.chapterId}</p>
              </div>
              <div>
                <p className="text-sm text-slate-400">Page ID</p>
                <p className="text-slate-200 font-medium text-sm truncate">{item.pageId || '—'}</p>
              </div>
              <div>
                <p className="text-sm text-slate-400">Last Read</p>
                <p className="text-slate-200 text-sm">
                  {new Date(item.lastReadAt).toLocaleString()}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useReader } from '@/hooks/useReader';
import { Star, Loader2 } from 'lucide-react';

export default function RatingsTab() {
  const { rateSeriesMutation, removeRating } = useReader();
  const [seriesId, setSeriesId] = useState('');
  const [rating, setRating] = useState<1 | 2 | 3 | 4 | 5>(5);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!seriesId.trim()) {
      alert('Please enter a series ID');
      return;
    }

    setIsSubmitting(true);
    try {
      await rateSeriesMutation.mutateAsync({
        seriesId,
        request: { value: rating },
      });
      setSeriesId('');
      setRating(5);
      alert('Rating submitted successfully!');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRemoveRating = async (id: string) => {
    if (confirm('Remove this rating?')) {
      await removeRating.mutateAsync(id);
    }
  };

  return (
    <div className="space-y-8">
      <div className="bg-slate-900 border border-slate-700 rounded-lg p-6">
        <h3 className="text-lg font-semibold text-slate-100 mb-4">Rate a Series</h3>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm text-slate-300 mb-2">Series ID</label>
            <input
              type="text"
              value={seriesId}
              onChange={(e) => setSeriesId(e.target.value)}
              placeholder="Enter series ID (UUID)"
              disabled={isSubmitting}
              className="w-full px-4 py-2 bg-slate-800 border border-slate-700 rounded-lg text-slate-100 placeholder-slate-500 focus:border-slate-600 focus:outline-none disabled:opacity-50"
            />
          </div>

          <div>
            <label className="block text-sm text-slate-300 mb-2">Rating</label>
            <div className="flex gap-2">
              {[1, 2, 3, 4, 5].map((value) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => setRating(value as 1 | 2 | 3 | 4 | 5)}
                  className={`p-2 rounded-lg transition ${
                    rating === value
                      ? 'bg-yellow-500/20 text-yellow-400'
                      : 'bg-slate-800 text-slate-400 hover:bg-slate-700'
                  }`}
                  disabled={isSubmitting}
                >
                  <Star className="h-6 w-6 fill-current" />
                </button>
              ))}
            </div>
          </div>

          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium disabled:opacity-50 transition"
          >
            {isSubmitting ? <Loader2 className="h-4 w-4 animate-spin inline mr-2" /> : null}
            Submit Rating
          </button>
        </form>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import DashboardLayoutWrapper from '@/components/layout/DashboardLayoutWrapper';
import { Plus, AlertCircle, CheckCircle2, X } from 'lucide-react';
import { useSeries } from '@/hooks/useSeries';
import SeriesGrid from './SeriesGrid';
import SeriesCreateModal from './SeriesCreateModal';
import SeriesEmptyState from './SeriesEmptyState';
import { CreateSeriesRequest } from '@/types/manga';

export default function SeriesPage() {
  const {
    series,
    isLoading,
    error,
    isCreating,
    successMessage,
    fetchSeries,
    createSeries,
    submitProposal,
    clearError,
    clearSuccess,
  } = useSeries();

  const [modalOpen, setModalOpen] = useState(false);
  const [submittingId, setSubmittingId] = useState<string | null>(null);

  // Auto clear notifications after 5 seconds
  useEffect(() => {
    if (error) {
      const timer = setTimeout(clearError, 5000);
      return () => clearTimeout(timer);
    }
  }, [error]);

  useEffect(() => {
    if (successMessage) {
      const timer = setTimeout(clearSuccess, 5000);
      return () => clearTimeout(timer);
    }
  }, [successMessage]);

  const handleCreateSubmit = async (data: CreateSeriesRequest) => {
    const newSeries = await createSeries(data);
    if (newSeries) {
      setModalOpen(false);
    }
  };

  const handleSubmitProposal = async (id: string) => {
    setSubmittingId(id);
    try {
      await submitProposal(id);
    } finally {
      setSubmittingId(null);
    }
  };

  return (
    <DashboardLayoutWrapper>
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">

        {/* Banner notifications */}
        <div className="space-y-3">
          {error && (
            <div className="flex items-center justify-between p-4 bg-rose-500/10 border border-rose-500/20 text-rose-200 rounded-xl text-xs font-semibold animate-in fade-in duration-200">
              <div className="flex items-center gap-2">
                <AlertCircle size={14} className="text-rose-400 shrink-0" />
                <span>{error}</span>
              </div>
              <button onClick={clearError} className="text-rose-400 hover:text-rose-200 transition-colors">
                <X size={14} />
              </button>
            </div>
          )}

          {successMessage && (
            <div className="flex items-center justify-between p-4 bg-emerald-500/10 border border-emerald-500/20 text-emerald-200 rounded-xl text-xs font-semibold animate-in fade-in duration-200">
              <div className="flex items-center gap-2">
                <CheckCircle2 size={14} className="text-emerald-400 shrink-0" />
                <span>{successMessage}</span>
              </div>
              <button onClick={clearSuccess} className="text-emerald-400 hover:text-emerald-200 transition-colors">
                <X size={14} />
              </button>
            </div>
          )}
        </div>

        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <h1 className="text-xl font-bold text-slate-100 mb-1">Manga Series</h1>
            <p className="text-xs text-slate-500 font-medium">Create, publish, and track serialization pipelines of registered titles.</p>
          </div>
          <button 
            onClick={() => setModalOpen(true)}
            className="flex items-center gap-2 px-4 py-2 bg-indigo-700 hover:bg-indigo-800 text-white font-semibold text-xs rounded-xl shadow-lg shadow-indigo-650/10 transition-all duration-200"
          >
            <Plus size={14} />
            Add Series
          </button>
        </div>

        {/* Loading / Content State */}
        {isLoading && series.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20">
            <div className="h-8 w-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
            <span className="text-xs text-slate-500 font-semibold mt-3">Loading series list...</span>
          </div>
        ) : series.length === 0 ? (
          <SeriesEmptyState onAddClick={() => setModalOpen(true)} />
        ) : (
          <SeriesGrid
            seriesList={series}
            onSubmitProposal={handleSubmitProposal}
            submittingId={submittingId}
          />
        )}
      </div>

      {/* Create Modal */}
      <SeriesCreateModal
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        onSubmit={handleCreateSubmit}
        isCreating={isCreating}
      />
    </DashboardLayoutWrapper>
  );
}

import React from 'react';
import { clsx } from 'clsx';
import { AlertTriangle, Calendar, Play, Send, Eye, Download, ShieldAlert } from 'lucide-react';
import { TaskItemUI } from '@/hooks/useTasks';
import TaskStatusBadge from './TaskStatusBadge';
import TaskPriorityBadge from './TaskPriorityBadge';
import { TaskStatus } from '@/types/manga';

interface TaskListTableProps {
  tasks: TaskItemUI[];
  selectedTaskId: string | undefined;
  onSelectTask: (t: TaskItemUI) => void;
  onStart: (id: string) => Promise<void>;
  onSubmitClick: (t: TaskItemUI) => void;
  onDownloadAsset: (fileAssetId: string, fileName: string) => Promise<void>;
  isStarting: boolean;
  isSubmitting: boolean;
}

export default function TaskListTable({
  tasks,
  selectedTaskId,
  onSelectTask,
  onStart,
  onSubmitClick,
  onDownloadAsset,
  isStarting,
  isSubmitting,
}: TaskListTableProps) {
  const handleActionButton = (e: React.MouseEvent, task: TaskItemUI) => {
    e.stopPropagation();
    if (task.status === TaskStatus.Todo) {
      onStart(task.id);
    } else if (task.status === TaskStatus.InProgress || task.status === TaskStatus.RevisionRequired) {
      onSubmitClick(task);
    }
  };

  return (
    <div className="bg-slate-900/30 border border-slate-800/80 rounded-xl overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="border-b border-slate-800 bg-slate-900/50 text-[10px] uppercase font-bold text-slate-455 tracking-wider">
              <th className="p-4">Task Name / Series</th>
              <th className="p-4">Chapter / Page</th>
              <th className="p-4">Annotation Type</th>
              <th className="p-4">Priority</th>
              <th className="p-4">Deadline</th>
              <th className="p-4">Status</th>
              <th className="p-4 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/60 text-xs text-slate-350">
            {tasks.map((task) => (
              <tr
                key={task.id}
                onClick={() => onSelectTask(task)}
                className={clsx(
                  'hover:bg-slate-900/20 transition-colors cursor-pointer group',
                  selectedTaskId === task.id && 'bg-indigo-950/20'
                )}
              >
                <td className="p-4">
                  <div className="space-y-0.5">
                    <div className="flex items-center gap-2">
                      <span className="font-bold text-slate-200 text-sm truncate max-w-[200px] sm:max-w-xs block" title={task.title}>
                        {task.title}
                      </span>
                      {task.isMock && (
                        <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[9px] font-bold bg-amber-500/10 text-amber-500 border border-amber-500/20 shrink-0">
                          <ShieldAlert size={8} />
                          Mock Data
                        </span>
                      )}
                    </div>
                    <span className="text-xs text-slate-500 block">{task.series}</span>
                  </div>
                </td>
                <td className="p-4 whitespace-nowrap">{task.chapter}</td>
                <td className="p-4">
                  <span className="text-[10px] font-medium text-slate-400 bg-slate-800/80 px-2.5 py-1 rounded-lg border border-slate-700/40">
                    {task.annotationType}
                  </span>
                </td>
                <td className="p-4">
                  <TaskPriorityBadge priority={task.priority} />
                </td>
                <td className="p-4 whitespace-nowrap">
                  <span className={clsx('flex items-center gap-1', task.deadlineOverdue ? 'text-rose-500 font-bold' : '')}>
                    {task.deadlineOverdue && <AlertTriangle size={12} />}
                    {task.deadline}
                  </span>
                </td>
                <td className="p-4">
                  <TaskStatusBadge status={task.status} />
                </td>
                <td className="p-4 text-right space-x-2 whitespace-nowrap">
                  {task.pageFileAssetId && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onDownloadAsset(task.pageFileAssetId!, `${task.title}_Reference.png`);
                      }}
                      className="p-1.5 hover:bg-slate-800 text-slate-400 hover:text-slate-200 rounded-md transition-colors"
                      title="Download reference page scan"
                    >
                      <Download size={14} />
                    </button>
                  )}
                  {task.status !== TaskStatus.Approved && task.status !== TaskStatus.Cancelled && (
                    <button
                      onClick={(e) => handleActionButton(e, task)}
                      disabled={isStarting || isSubmitting || task.status === TaskStatus.Submitted}
                      className={clsx(
                        'px-2.5 py-1 text-[10px] font-bold rounded-lg border uppercase transition-all shadow-sm',
                        task.status === TaskStatus.Todo && 'bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white border-indigo-500/20 hover:border-indigo-600',
                        (task.status === TaskStatus.InProgress || task.status === TaskStatus.RevisionRequired) && 'bg-emerald-600/10 hover:bg-emerald-600 text-emerald-400 hover:text-white border-emerald-500/20 hover:border-emerald-600',
                        task.status === TaskStatus.Submitted && 'bg-slate-800/40 text-slate-500 border-slate-700/30 cursor-not-allowed'
                      )}
                    >
                      {task.status === TaskStatus.Todo ? 'Start' : task.status === TaskStatus.Submitted ? 'Submitted' : 'Submit'}
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

