  });

  test('Full-stack revision, resubmission and approval flow', async ({ page }) => {
    if (!isBackendLive) {
      test.skip(true, 'Skipping fullstack E2E because backend is not running.');
      return;
    }

    // Console logs for E2E visibility
    page.on('console', msg => {
