import { useState, useEffect } from 'react';
import { editorialApi } from '@/services/editorial-api';
import { mangaApi } from '@/services/manga-api';
import { IssueResponse, RankingItemResponse, CancellationWarningResponse } from '@/types/editorial';
import { SeriesResponse } from '@/types/manga';

export interface MangakaSeriesRanking {
  seriesId: string;
  seriesTitle: string;
  rank: number;
  votes: number;
  trend: 'up' | 'down' | 'stable';
  hasWarning: boolean;
}

export function useMangakaRankings() {
  const [issues, setIssues] = useState<IssueResponse[]>([]);
  const [selectedIssueId, setSelectedIssueId] = useState<string>('');
  const [rankings, setRankings] = useState<MangakaSeriesRanking[]>([]);
  const [cancellationWarnings, setCancellationWarnings] = useState<CancellationWarningResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingRanking, setLoadingRanking] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Cache series id→title so we only call /manga/series once per session.
  const [seriesTitleCache, setSeriesTitleCache] = useState<Map<string, string>>(new Map());

  const fetchIssues = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await editorialApi.getIssues();
      if (res.data?.success) {
        const issueList = res.data.data || [];
        setIssues(issueList);
        if (issueList.length > 0 && !selectedIssueId) {
          setSelectedIssueId(issueList[0].id);
          void loadRankingsForIssue(issueList[0].id);
        }
      } else {
        setError(res.data?.message || 'Failed to load issues.');
      }
    } catch (err: any) {
      const msg = err.response?.data?.message || err.response?.data?.error || 'Could not reach editorial service.';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  const loadRankingsForIssue = async (issueId: string) => {
    if (!issueId) return;
    setLoadingRanking(true);
    setError(null);
    try {
      // Fetch rankings and the series list in parallel.
      // Series list gives us the real titles to display.
      const [rankingsRes, seriesRes] = await Promise.all([
        editorialApi.getRankings(issueId),
        mangaApi.getSeries(),
      ]);

      // Build seriesId→title map; merge into the persistent cache.
      const newCache = new Map(seriesTitleCache);
      if (seriesRes.data?.success) {
        (seriesRes.data.data || []).forEach((s: SeriesResponse) => {
          newCache.set(s.id, s.title);
        });
        setSeriesTitleCache(newCache);
      }

      if (rankingsRes.data?.success) {
        const rankingSnapshots = rankingsRes.data.data || [];
        const mappedRankings: MangakaSeriesRanking[] = (rankingSnapshots[0]?.items || []).map(
          (item: RankingItemResponse, index: number) => ({
            seriesId: item.seriesId,
            // Use the real title; fall back gracefully only if lookup fails.
            seriesTitle: newCache.get(item.seriesId) ?? `Series ${item.seriesId.slice(0, 8)}`,
            rank: item.rankPosition || index + 1,
            votes: item.voteCount || 0,
            trend: (item.trend as 'up' | 'down' | 'stable') || 'stable',
            hasWarning: item.riskLevel !== 'Low',
          })
        );
        setRankings(mappedRankings);
      } else {
        setRankings([]);
        setError(rankingsRes.data?.message || 'Could not load rankings.');
      }
    } catch (err: any) {
      setRankings([]);
      setError(err.response?.data?.message || 'Could not reach editorial service.');
    } finally {
      setLoadingRanking(false);
    }
  };

  const handleIssueChange = async (issueId: string) => {
    setSelectedIssueId(issueId);
    void loadRankingsForIssue(issueId);
  };

  useEffect(() => {
    void fetchIssues();
  }, []);

  return {
    issues,
    selectedIssueId,
    rankings,
    loading,
    loadingRanking,
    error,
    handleIssueChange,
    fetchIssues,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { mangaApi } from '@/services/manga-api';
import { AnnotationResponse, AnnotationType } from '@/types/manga';

export interface AnnotationData {
  type: AnnotationType;
  description?: string;
  notes?: string;
  coordinatesJson?: string; // JSON string of {x, y, width, height}
}

export function usePageAnnotations(pageId: string | null) {
  const [annotations, setAnnotations] = useState<AnnotationResponse[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchAnnotations = useCallback(async () => {
    if (!pageId) {
      setAnnotations([]);
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const res = await mangaApi.getPageAnnotations(pageId);
      if (res.data?.success) {
        setAnnotations(res.data.data || []);
      } else {
        setError(res.data?.message || 'Failed to load annotations.');
      }
    } catch (err: unknown) {
      const msg = (err as any)?.response?.data?.message || (err as any)?.response?.data?.error || 'Could not load annotations.';
      setError(msg);
    } finally {
      setLoading(false);
    }
  }, [pageId]);

  const createAnnotation = async (annotationData: AnnotationData) => {
    if (!pageId) return false;

    try {
      const res = await mangaApi.createAnnotation(pageId, {
        type: annotationData.type,
        description: annotationData.description,
        notes: annotationData.notes,
        coordinatesJson: annotationData.coordinatesJson,
      });

      if (res.data?.success) {
        await fetchAnnotations();
        return true;
      } else {
        setError(res.data?.message || 'Failed to create annotation.');
        return false;
      }
    } catch (err: unknown) {
      const msg = (err as any)?.response?.data?.message || (err as any)?.response?.data?.error || 'Could not create annotation.';
      setError(msg);
      return false;
    }
  };

  const deleteAnnotation = async (annotationId: string) => {
    try {
      const res = await mangaApi.deleteAnnotation(annotationId);
      if (res.data?.success) {
        await fetchAnnotations();
        return true;
      } else {
        setError(res.data?.message || 'Failed to delete annotation.');
        return false;
      }
    } catch (err: unknown) {
      const msg = (err as any)?.response?.data?.message || (err as any)?.response?.data?.error || 'Could not delete annotation.';
      setError(msg);
      return false;
    }
  };

  useEffect(() => {
    setTimeout(() => {
      void fetchAnnotations();
    }, 0);
  }, [fetchAnnotations]);

  return {
    annotations,
    loading,
    error,
    fetchAnnotations,
    createAnnotation,
    deleteAnnotation,
  };
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { readerApi } from '@/services/reader-api';
import { 
  CreateBookmarkRequest,
  SaveReadingProgressRequest,
  UpsertRatingRequest,
  CreateCommentRequest,
  UpdateCommentRequest
} from '@/types/reader';

export const useReader = () => {
  const queryClient = useQueryClient();

  // Favorites
  const { data: favorites = [], isLoading: favoritesLoading } = useQuery({
    queryKey: ['favorites'],
    queryFn: async () => {
      const res = await readerApi.getFavorites(1, 100);
      return res.data.data || [];
    },
  });

  const addFavorite = useMutation({
    mutationFn: (seriesId: string) => readerApi.addFavorite(seriesId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['favorites'] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  const removeFavorite = useMutation({
    mutationFn: (seriesId: string) => readerApi.removeFavorite(seriesId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['favorites'] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  // Bookmarks
  const { data: bookmarks = [], isLoading: bookmarksLoading } = useQuery({
    queryKey: ['bookmarks'],
    queryFn: async () => {
      const res = await readerApi.getBookmarks(1, 100);
      return res.data.data || [];
    },
  });

  const addBookmark = useMutation({
    mutationFn: (request: CreateBookmarkRequest) => readerApi.addBookmark(request),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bookmarks'] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  const removeBookmark = useMutation({
    mutationFn: (id: string) => readerApi.removeBookmark(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bookmarks'] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  // History
  const { data: history = [], isLoading: historyLoading } = useQuery({
    queryKey: ['reading-history'],
    queryFn: async () => {
      const res = await readerApi.getHistory(1, 100);
      return res.data.data || [];
    },
  });

  const saveProgress = useMutation({
    mutationFn: (request: SaveReadingProgressRequest) => readerApi.saveProgress(request),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['reading-history'] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  const continueReading = useQuery({
    queryKey: ['continue-reading'],
    queryFn: async () => {
      const res = await readerApi.continueReading();
      return res.data.data || null;
    },
  });

  const clearHistory = useMutation({
    mutationFn: () => readerApi.clearHistory(),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['reading-history'] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  // Ratings
  const getRatingSummary = (seriesId: string) => {
    return useQuery({
      queryKey: ['rating-summary', seriesId],
      queryFn: async () => {
        const res = await readerApi.getRatingSummary(seriesId);
        return res.data.data || null;
      },
    });
  };

  const rateSeriesMutation = useMutation({
    mutationFn: (params: { seriesId: string; request: UpsertRatingRequest }) =>
      readerApi.rate(params.seriesId, params.request),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['rating-summary', variables.seriesId] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  const removeRating = useMutation({
    mutationFn: (seriesId: string) => readerApi.removeRating(seriesId),
    onSuccess: (_, seriesId) => {
      queryClient.invalidateQueries({ queryKey: ['rating-summary', seriesId] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  // Comments
  const getSeriesComments = (seriesId: string) => {
    return useQuery({
      queryKey: ['series-comments', seriesId],
      queryFn: async () => {
        const res = await readerApi.getSeriesComments(seriesId, 1, 100);
        return res.data.data || [];
      },
    });
  };

  const getChapterComments = (chapterId: string) => {
    return useQuery({
      queryKey: ['chapter-comments', chapterId],
      queryFn: async () => {
        const res = await readerApi.getChapterComments(chapterId, 1, 100);
        return res.data.data || [];
      },
    });
  };

  const addSeriesComment = useMutation({
    mutationFn: (params: { seriesId: string; request: CreateCommentRequest }) =>
      readerApi.addSeriesComment(params.seriesId, params.request),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['series-comments', variables.seriesId] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  const addChapterComment = useMutation({
    mutationFn: (params: { chapterId: string; request: CreateCommentRequest }) =>
      readerApi.addChapterComment(params.chapterId, params.request),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['chapter-comments', variables.chapterId] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  const updateComment = useMutation({
    mutationFn: (params: { id: string; request: UpdateCommentRequest }) =>
      readerApi.updateComment(params.id, params.request),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['series-comments'] });
      queryClient.invalidateQueries({ queryKey: ['chapter-comments'] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  const deleteComment = useMutation({
    mutationFn: (id: string) => readerApi.deleteComment(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['series-comments'] });
      queryClient.invalidateQueries({ queryKey: ['chapter-comments'] });
      queryClient.invalidateQueries({ queryKey: ['activity-summary'] });
    },
  });

  // Activity Summary
  const { data: activitySummary } = useQuery({
    queryKey: ['activity-summary'],
    queryFn: async () => {
      const res = await readerApi.getActivitySummary();
      return res.data.data || null;
    },
  });

  return {
    // Favorites
    favorites,
    favoritesLoading,
    addFavorite,
    removeFavorite,

    // Bookmarks
    bookmarks,
    bookmarksLoading,
    addBookmark,
    removeBookmark,

    // History
    history,
    historyLoading,
    saveProgress,
    continueReading,
    clearHistory,

    // Ratings
    getRatingSummary,
    rateSeriesMutation,
    removeRating,

    // Comments
    getSeriesComments,
    getChapterComments,
    addSeriesComment,
    addChapterComment,
    updateComment,
    deleteComment,

    // Activity
    activitySummary,
  };
};

