import { useState, useEffect } from 'react';
import { mangaApi } from '@/services/manga-api';
import { SeriesResponse, CreateSeriesRequest } from '@/types/manga';

export function useSeries() {
  const [series, setSeries] = useState<SeriesResponse[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isCreating, setIsCreating] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const clearError = () => setError(null);
  const clearSuccess = () => setSuccessMessage(null);

  const fetchSeries = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await mangaApi.getSeries();
      if (res.data && res.data.success) {
        setSeries(res.data.data);
      } else {
        setError(res.data?.message || 'Failed to fetch series.');
      }
    } catch (err: any) {
      handleApiError(err, 'fetch list of');
    } finally {
      setIsLoading(false);
    }
  };

  const createSeries = async (payload: CreateSeriesRequest) => {
    setIsCreating(true);
    setError(null);
    setSuccessMessage(null);
    try {
      const res = await mangaApi.createSeries(payload);
      if (res.data && res.data.success) {
        const newSeries = res.data.data;
        setSeries((prev) => [newSeries, ...prev]);
        setSuccessMessage(`Series "${newSeries.title}" created successfully!`);
        return newSeries;
      } else {
        setError(res.data?.message || 'Failed to create series.');
      }
    } catch (err: any) {
      handleApiError(err, 'create');
    } finally {
      setIsCreating(false);
    }
  };

  const submitProposal = async (id: string) => {
    setError(null);
    setSuccessMessage(null);
    try {
      const res = await mangaApi.submitProposal(id);
      if (res.data && res.data.success) {
        setSeries((prev) =>
          prev.map((s) =>
            s.id === id ? { ...s, status: 2 } : s
          )
        );
        setSuccessMessage('Series proposal submitted successfully.');
      } else {
        setError(res.data?.message || 'Failed to submit proposal.');
      }
    } catch (err: any) {
      handleApiError(err, 'submit proposal for');
    }
  };

  const handleApiError = (err: any, action: string) => {
    const status = err.response?.status;
    let msg = `An error occurred while trying to ${action} series.`;

    if (status === 401) {
      msg = 'Phiên làm việc hết hạn. Vui lòng đăng nhập lại.';
    } else if (status === 403) {
      msg = 'Bạn không có quyền thực hiện hành động này.';
    } else if (status === 404) {
      msg = 'Series không tồn tại trên hệ thống.';
    } else if (status >= 500) {
      msg = 'Dịch vụ manga tạm thời không khả dụng. Vui lòng thử lại sau.';
    } else {
      msg = err.response?.data?.message || err.message || msg;
    }

    setError(msg);
  };

  useEffect(() => {
    fetchSeries();
  }, []);

  return {
    series,
    isLoading,
    error,
    isCreating,
    successMessage,
    fetchSeries,
    createSeries,
    submitProposal,
    clearError,
    clearSuccess,
  };
}

import { NotificationResponse, NotificationType } from '@/types/notification';

/**
 * Resolves a notification response to a type-safe relative route.
 * Prevents javascript: or external redirect vulnerabilities.
 */
export function resolveNotificationRoute(notification: NotificationResponse): string {
  // If the server provided a validated ActionUrl, verify it is relative
  if (notification.actionUrl) {
    const trimmed = notification.actionUrl.trim();
    if (trimmed.startsWith('/') && !trimmed.startsWith('//')) {
      return trimmed;
    }
  }

  const { type, resourceId, resourceType } = notification;

  // Fallback if type is missing or unknown
  switch (type) {
    case NotificationType.TaskAssigned:
      return resourceId ? `/tasks?taskId=${resourceId}` : '/tasks';

    case NotificationType.TaskSubmitted:
    case NotificationType.TaskApproved:
      return resourceId ? `/tasks?taskId=${resourceId}` : '/tasks';

    case NotificationType.ChapterSubmittedForReview:
      return resourceId ? `/editorial?chapterId=${resourceId}` : '/editorial';

    case NotificationType.ChapterApproved:
    case NotificationType.ChapterRevisionRequested:
    case NotificationType.ChapterRejected:
      return resourceId ? `/series/chapters/${resourceId}` : '/series';

    case NotificationType.RankingCalculated:
      return resourceId ? `/board?tab=Rankings&issueId=${resourceId}` : '/board';

    case NotificationType.CancellationWarning:
    case NotificationType.CancellationWarningCreated:
      return resourceId ? `/series/${resourceId}` : '/board';

    case NotificationType.ProposalSubmitted:
      return resourceId ? `/board?tab=Proposals&seriesId=${resourceId}` : '/board';

    case NotificationType.ProposalApproved:
    case NotificationType.ProposalRejected:
    case NotificationType.SeriesCancelled:
    case NotificationType.SeriesHiatus:
      return resourceId ? `/series/${resourceId}` : '/series';

    default:
      return '/notifications';
  }
}

import * as signalR from '@microsoft/signalr';

const baseURL = process.env.NEXT_PUBLIC_API_BASE_URL || 'http://localhost:5200';

export function createSignalRConnection(getToken: () => string): signalR.HubConnection {
  // Use YARP route /notifications/hub or directly /hub
  const hubUrl = `${baseURL}/notifications/hub`;

  const connection = new signalR.HubConnectionBuilder()
    .withUrl(hubUrl, {
      accessTokenFactory: () => getToken() || '',
    })
    .withAutomaticReconnect([0, 1000, 3000, 5000, 10000])
    .configureLogging(signalR.LogLevel.None)
    .build();

  return connection;
}

/**
 * Safely starts a hub connection, catching any errors (e.g. if Hub endpoint is not configured)
 */
export async function startSignalRConnection(connection: signalR.HubConnection): Promise<boolean> {
  if (connection.state === signalR.HubConnectionState.Disconnected) {
    try {
      await connection.start();
      console.log('[SignalR] Connected successfully.');
      return true;
    } catch (err: any) {
      const errMsg = err?.message || String(err);
      if (errMsg.includes('stopped during negotiation') || errMsg.includes('negotiation was stopped')) {
        console.log('[SignalR] Connection negotiation aborted (normal during component unmount).');
      } else {
        console.warn('[SignalR] Hub connection failed to start. Notifications will poll instead. Error:', err);
      }
      return false;
    }
  }
  return connection.state === signalR.HubConnectionState.Connected;
}

/**
 * Stop SignalR connection cleanly
 */
export async function stopSignalRConnection(connection: signalR.HubConnection) {
  try {
    if (connection.state !== signalR.HubConnectionState.Disconnected) {
      await connection.stop();
      console.log('[SignalR] Connection stopped.');
    }
  } catch (err) {
    console.warn('[SignalR] Error stopping connection:', err);
  }
}

/**
 * Admin API Service
 * All calls go through API Gateway at NEXT_PUBLIC_API_BASE_URL
 */
import { api } from '@/lib/api';
import { ApiResponse } from '@/types/api';

// --- Types ---
export interface AdminUserListItem {
  id: string;
  displayName: string;
  email: string;
  username?: string;
  roles: string[];
  status: number; // 1 = Active, 2 = Disabled, 3 = Locked
  emailVerified: boolean;
  createdAt: string;
  lastLoginAt?: string;
  lockoutUntil?: string;
}

export interface AdminSecurityEvent {
  actorUserId: string;
  action: string;
  createdAt: string;
}

export interface AdminUserDetail extends AdminUserListItem {
  lockoutUntil?: string;
  permissions: string[];
  recentSecurityEvents: AdminSecurityEvent[];
}

export interface AdminUserListQuery {
  page?: number;
  pageSize?: number;
  search?: string;
  role?: string;
  status?: string; // "Active", "Disabled", "Locked"
  sortBy?: string;
  sortDirection?: string;
}

export interface AdminRoleCatalog {
  id: string;
  name: string;
  description?: string;
  permissions: string[];
}

export interface AdminAuditLogItem {
  id: string;
  action: string;
  details?: string | null;
  createdAt: string;
}

export interface StudioResponse {
  id: string;
  name: string;
  description?: string;
  ownerId: string;
  createdAt: string;
  updatedAt?: string;
}

export interface AdminCreateSeriesRequest {
  studioId: string;
  title: string;
  description?: string;
  genre?: string;
}

export interface PagedResponse<T> {
  items: T[];
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
  hasNextPage: boolean;
  hasPreviousPage: boolean;
}

export const adminApi = {
  // --- User Administration (/identity/admin) ---
  
  listUsers: (query: AdminUserListQuery) =>
    api.get<ApiResponse<PagedResponse<AdminUserListItem>>>('/identity/admin/users', { params: query }),

  getUserDetail: (userId: string) =>
    api.get<ApiResponse<AdminUserDetail>>(`/identity/admin/users/${userId}`),

  updateUserStatus: (userId: string, data: { status: number; lockoutUntil?: string | null }) =>
    api.patch<ApiResponse<any>>(`/identity/admin/users/${userId}/status`, data),

  updateUserRoles: (userId: string, data: { roles: string[] }) =>
    api.patch<ApiResponse<any>>(`/identity/admin/users/${userId}/roles`, data),

  createUser: (data: { email: string; username: string; fullName: string; password: string; roles: string[] }) =>
    api.post<ApiResponse<any>>('/identity/admin/users', data),

  updateUser: (userId: string, data: { username: string; fullName: string }) =>
    api.patch<ApiResponse<any>>(`/identity/admin/users/${userId}`, data),

  deleteUser: (userId: string) =>
    api.delete<ApiResponse<boolean>>(`/identity/admin/users/${userId}`),

  lockUser: (userId: string, data: { lockoutUntil?: string | null; reason: string }) =>
    api.post<ApiResponse<any>>(`/identity/admin/users/${userId}/lock`, data),

  unlockUser: (userId: string) =>
    api.post<ApiResponse<any>>(`/identity/admin/users/${userId}/unlock`),

  resetUserPassword: (userId: string, data: { newPassword: string }) =>
    api.post<ApiResponse<any>>(`/identity/admin/users/${userId}/reset-password`, data),

  revokeUserSessions: (userId: string) =>
    api.post<ApiResponse<any>>(`/identity/admin/users/${userId}/revoke-sessions`),

  getRoles: () =>
    api.get<ApiResponse<AdminRoleCatalog[]>>('/identity/admin/roles'),

  createRole: (data: { name: string; description?: string }) =>
    api.post<ApiResponse<AdminRoleCatalog>>('/identity/admin/roles', data),

  updateRole: (roleId: string, data: { description?: string }) =>
    api.patch<ApiResponse<AdminRoleCatalog>>(`/identity/admin/roles/${roleId}`, data),

  retireRole: (roleId: string) =>
    api.delete<ApiResponse<boolean>>(`/identity/admin/roles/${roleId}`),

  replaceRolePermissions: (roleId: string, data: { permissionKeys: string[] }) =>
    api.put<ApiResponse<AdminRoleCatalog>>(`/identity/admin/roles/${roleId}/permissions`, data),

  getPermissions: () =>
    api.get<ApiResponse<string[]>>('/identity/admin/permissions'),

  getAuditLogs: (query?: { page?: number; pageSize?: number }) =>
    api.get<ApiResponse<PagedResponse<AdminAuditLogItem>>>('/identity/admin/audit-logs', { params: query }),

  // --- Studio & Series Administration (/manga) ---
  
  listStudios: () =>
    api.get<ApiResponse<StudioResponse[]>>('/manga/studios/my'),

  createStudio: (data: { name: string; description?: string }) =>
    api.post<ApiResponse<StudioResponse>>('/manga/studios', data),

  createSeries: (data: AdminCreateSeriesRequest) =>
    api.post<ApiResponse<any>>('/manga/series', data),

  updateSeries: (seriesId: string, data: { title?: string; description?: string; genre?: string; status?: number }) =>
    api.patch<ApiResponse<any>>(`/manga/series/${seriesId}`, data),

  createChapter: (seriesId: string, data: { chapterNumber: number; title: string }) =>
    api.post<ApiResponse<any>>(`/manga/series/${seriesId}/chapters`, data),

  getChapters: (seriesId: string) =>
    api.get<ApiResponse<any[]>>(`/manga/series/${seriesId}/chapters`),

  getChapterPages: (chapterId: string) =>
    api.get<ApiResponse<any[]>>(`/manga/chapters/${chapterId}/pages`),

  createPage: (chapterId: string, data: { pageNumber: number; fileId: string }) =>
    api.post<ApiResponse<any>>(`/manga/chapters/${chapterId}/pages`, data),

  publishChapter: (chapterId: string) =>
    api.patch<ApiResponse<any>>(`/manga/chapters/${chapterId}/status`, { status: 7 }), // Status 7 = Published
};

/**
 * File API Service
 * All calls go through API Gateway at NEXT_PUBLIC_API_BASE_URL
 * Route: /files/**
 */
import { api } from '@/lib/api';
import { ApiResponse } from '@/types/api';
import {
  FileAssetResponse,
  FileUploadResponse,
  FileVersionResponse,
  FileUrlResponse,
  FileCategory,
} from '@/types/file';

export const fileApi = {
  /**
   * POST /files/upload
   * Uploads a file using multipart/form-data.
   * Returns FileUploadResponse with the new file's ID and URL.
   */
  uploadFile: (
    file: File,
    category: FileCategory = 'Other',
    metadata?: Record<string, string>,
    onUploadProgress?: (progressEvent: any) => void
  ) => {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('category', category);
    if (metadata) {
      Object.entries(metadata).forEach(([key, value]) => formData.append(key, value));
    }
    return api.post<ApiResponse<FileUploadResponse>>('/files/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
      onUploadProgress,
    });
  },

  /**
   * GET /files/my
   * Returns files belonging to the current user
   */
  getMyFiles: () =>
    api.get<ApiResponse<FileAssetResponse[]>>('/files/my'),

  /**
   * GET /files/{id}
   * Returns file metadata (no binary content)
   */
  getFileMetadata: (id: string) =>
    api.get<ApiResponse<FileAssetResponse>>(`/files/${id}`),

  /**
   * GET /files/{id}/url
   * Returns a pre-signed or direct download URL for the file
   */
  getFileUrl: (id: string) =>
    api.get<ApiResponse<FileUrlResponse>>(`/files/${id}/url`).then((response) => {
      const dataObj = response.data?.data;
      return {
        ...response,
        data: {
          ...response.data,
          data: dataObj ? { ...dataObj, url: dataObj.publicUrl ?? '' } : undefined,
        },
      };
    }),

  /**
   * GET /files/{id}/download
   * Downloads the file as a Blob (binary stream)
   */
  downloadFile: (id: string) =>
    api.get<Blob>(`/files/${id}/download`, { responseType: 'blob' }),

  /**
   * GET /files/{id}/versions
   * Returns all versions of a file asset
   */
  getFileVersions: (id: string) =>
    api.get<ApiResponse<FileVersionResponse[]>>(`/files/${id}/versions`),

  /**
   * POST /files/{id}/versions
   * Creates a new version of an existing file
   */
  createVersion: (id: string, file: File) => {
    const data = new FormData();
    data.append('file', file);
    return api.post<ApiResponse<FileVersionResponse>>(`/files/${id}/versions`, data, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
  },

  /**
   * DELETE /files/{id}
   * Deletes a file asset
   */
  deleteFile: (id: string) => api.delete<ApiResponse<object>>(`/files/${id}`),
};

import { create } from 'zustand';
import { NotificationResponse } from '@/types/notification';
import { api } from '@/lib/api';
import { ApiResponse } from '@/types/api';

interface NotificationState {
  notifications: NotificationResponse[];
  unreadCount: number;
  isLoading: boolean;
  error: string | null;
  lastSeenNotificationIds: Set<string>;
  activeToast: NotificationResponse | null;
  clearToast: () => void;
  fetchNotifications: () => Promise<void>;
  fetchUnreadCount: () => Promise<void>;
  markAsRead: (id: string) => Promise<void>;
  markAllAsRead: () => Promise<void>;
  deleteNotification: (id: string) => Promise<void>;
  addNotification: (notification: NotificationResponse) => void;
  clearError: () => void;
  reconcileAfterReconnect: () => Promise<void>;
}

export const useNotificationStore = create<NotificationState>((set, get) => ({
  notifications: [],
  unreadCount: 0,
  isLoading: false,
  error: null,
  lastSeenNotificationIds: new Set(),
  activeToast: null,

  clearToast: () => set({ activeToast: null }),
  clearError: () => set({ error: null }),

  fetchNotifications: async () => {
    set({ isLoading: true, error: null });
    try {
      const response = await api.get<ApiResponse<NotificationResponse[]>>('/notifications/my');
      if (response.data && response.data.success) {
        const notifications = response.data.data || [];
        const seenIds = new Set(notifications.map((n) => n.id));
        set({ 
          notifications, 
          lastSeenNotificationIds: seenIds,
        });
      } else {
        set({ error: response.data.message || 'Failed to load notifications.' });
      }
    } catch (err: any) {
      const message =
        err.response?.data?.message ||
        err.response?.data?.error ||
        'Could not reach notification service. Please try again.';
      set({ error: message });
    } finally {
      set({ isLoading: false });
    }
  },

  fetchUnreadCount: async () => {
    try {
      const response = await api.get<ApiResponse<{ unreadCount: number; count: number }>>('/notifications/unread-count');
      if (response.data && response.data.success) {
        const countVal = response.data.data.unreadCount !== undefined ? response.data.data.unreadCount : response.data.data.count;
        set({ unreadCount: countVal || 0 });
      }
      // silently skip on error – unread badge is non-critical
    } catch {
      // Non-critical: do not set error state for unread count
    }
  },

  markAsRead: async (id: string) => {
    try {
      const response = await api.post<ApiResponse<NotificationResponse>>(`/notifications/${id}/read`);
      if (response.data && response.data.success) {
        const wasUnread = get().notifications.find((n) => n.id === id)?.status === 1;
        const updatedNotifications = get().notifications.map((n) =>
          n.id === id ? { ...n, status: 2, readAt: new Date().toISOString() } : n
        );
        set({
          notifications: updatedNotifications,
          unreadCount: Math.max(0, get().unreadCount - (wasUnread ? 1 : 0)),
        });
      } else {
        set({ error: response.data.message || 'Failed to mark notification as read.' });
      }
    } catch (err: any) {
      const message = err.response?.data?.message || err.response?.data?.error || 'Failed to mark notification as read.';
      set({ error: message });
    }
  },

  markAllAsRead: async () => {
    try {
      const response = await api.post<ApiResponse<{ unreadCount: number }>>('/notifications/read-all');
      if (response.data && response.data.success) {
        const updatedNotifications = get().notifications.map((n) => ({
          ...n,
          status: 2,
          readAt: new Date().toISOString(),
        }));
        set({ notifications: updatedNotifications, unreadCount: 0 });
      } else {
        set({ error: response.data.message || 'Failed to mark all notifications as read.' });
      }
    } catch (err: any) {
      const message = err.response?.data?.message || err.response?.data?.error || 'Failed to mark all as read.';
      set({ error: message });
    }
  },

  deleteNotification: async (id: string) => {
    try {
      const response = await api.delete<ApiResponse<null>>(`/notifications/${id}`);
      if (response.data && response.data.success) {
        const deleted = get().notifications.find((n) => n.id === id);
        const wasUnread = deleted?.status === 1;
        set({
          notifications: get().notifications.filter((n) => n.id !== id),
          unreadCount: Math.max(0, get().unreadCount - (wasUnread ? 1 : 0)),
        });
      } else {
        set({ error: response.data.message || 'Failed to delete notification.' });
      }
    } catch (err: any) {
      const message = err.response?.data?.message || err.response?.data?.error || 'Failed to delete notification.';
      set({ error: message });
    }
  },

  addNotification: (notification: NotificationResponse) => {
    set((state) => {
      // Deduplication: check if we've already seen this notification
      if (state.lastSeenNotificationIds.has(notification.id)) {
        console.log(`[Notification] Skipped duplicate: ${notification.id}`);
        return state;
      }

      // Check if notification already exists in list
      if (state.notifications.some((n) => n.id === notification.id)) {
        console.log(`[Notification] Notification already in list: ${notification.id}`);
        return state;
      }

      const newLastSeenIds = new Set(state.lastSeenNotificationIds);
      newLastSeenIds.add(notification.id);

      const isUnread = notification.status === 1;

      return {
        ...state,
        notifications: [notification, ...state.notifications],
        unreadCount: state.unreadCount + (isUnread ? 1 : 0),
        lastSeenNotificationIds: newLastSeenIds,
        activeToast: notification,
      };
    });
  },

  reconcileAfterReconnect: async () => {
    set({ isLoading: true });
    try {
      // Fetch fresh notifications after reconnect
      const response = await api.get<ApiResponse<NotificationResponse[]>>('/notifications/my');
      if (response.data && response.data.success) {
        const freshNotifications = response.data.data || [];
        // Clear seen IDs and repopulate from server
        const newLastSeenIds = new Set(freshNotifications.map((n) => n.id));
        set({
          notifications: freshNotifications,
          lastSeenNotificationIds: newLastSeenIds,
        });
        console.log(`[Notification] Reconciled after reconnect: ${freshNotifications.length} notifications`);
      }
    } catch (err) {
      console.warn('[Notification] Failed to reconcile after reconnect:', err);
    } finally {
      set({ isLoading: false });
    }
  },
}));

